// ─────────────────────────────────────────
//  AUDIO MANAGER — Música épica
// ─────────────────────────────────────────
class AudioManager {
  static final AudioManager _instance = AudioManager._internal();
  factory AudioManager() => _instance;
  AudioManager._internal();

  final AudioPlayer _playerMusica = AudioPlayer();
  final AudioPlayer _playerCelebracion = AudioPlayer();

  bool _musicaIniciada = false;
  bool _silenciado = false;
  double _volumenMusica = 0.4;
  double _volumenEfectos = 0.5;

  bool get silenciado => _silenciado;
  double get volumenMusica => _volumenMusica;
  double get volumenEfectos => _volumenEfectos;

  /// Carga las preferencias de audio guardadas (silenciado, volúmenes).
  /// Se llama al iniciar la app para mantener la configuración del usuario
  /// incluso después de cerrar y reabrir la app.
  Future<void> cargarPreferencias() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      _silenciado = prefs.getBool('audio_silenciado') ?? false;
      _volumenMusica = prefs.getDouble('audio_volumen_musica') ?? 0.4;
      _volumenEfectos = prefs.getDouble('audio_volumen_efectos') ?? 0.5;
    } catch (e) {
      debugPrint('⚠️ Error cargando preferencias audio: $e');
    }
  }

  /// Guarda las preferencias actuales en SharedPreferences
  Future<void> _guardarPreferencias() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('audio_silenciado', _silenciado);
      await prefs.setDouble('audio_volumen_musica', _volumenMusica);
      await prefs.setDouble('audio_volumen_efectos', _volumenEfectos);
    } catch (e) {
      debugPrint('⚠️ Error guardando preferencias audio: $e');
    }
  }

  Future<void> iniciarMusicaPrincipal() async {
    if (_musicaIniciada) return;
    _musicaIniciada = true;
    try {
      await _playerMusica.setReleaseMode(ReleaseMode.loop);
      await _playerMusica.setVolume(_silenciado ? 0 : _volumenMusica);
      await _playerMusica.play(AssetSource('audio/musica_principal.mp3'));
    } catch (e) {
      debugPrint('🔴 Error música: $e');
      _musicaIniciada = false;
    }
  }

  Future<void> setVolumenMusica(double volumen) async {
    _volumenMusica = volumen.clamp(0.0, 1.0);
    if (!_silenciado) {
      await _playerMusica.setVolume(_volumenMusica);
    }
    await _guardarPreferencias();
  }

  Future<void> setVolumenEfectos(double volumen) async {
    _volumenEfectos = volumen.clamp(0.0, 1.0);
    await _guardarPreferencias();
  }

  Future<void> toggleSilencio() async {
    _silenciado = !_silenciado;
    await _playerMusica.setVolume(_silenciado ? 0 : _volumenMusica);
    await _guardarPreferencias();
  }

  Future<void> pausarMusica() async {
    try { await _playerMusica.pause(); } catch (_) {}
  }

  Future<void> reanudarMusica() async {
    try { await _playerMusica.resume(); } catch (_) {}
  }

  Future<void> sonarCelebracion() async {
    if (_silenciado) return;
    try {
      await _playerCelebracion.setVolume(_volumenEfectos);
      await _playerCelebracion.play(AssetSource('audio/celebracion.mp3'));
    } catch (e) {
      debugPrint('🔴 Error celebración: $e');
    }
  }

  void dispose() {
    _musicaIniciada = false;
    _playerMusica.dispose();
    _playerCelebracion.dispose();
  }
}

// ═══════════════════════════════════════════════════════════════
//  SESIÓN MANAGER — Persiste el contexto del usuario entre sesiones
// ═══════════════════════════════════════════════════════════════
//  Resuelve el problema: cuando el usuario cierra la app
//  por seguridad y la vuelve a abrir, debe encontrar:
//   - La misma ruta que estaba haciendo
//   - El último sitio que validó
//   - Sus configuraciones (sonido, idioma, modo demo si es admin)
//
//  Almacenamiento: SharedPreferences (local, sobrevive a app cerrada)
// ═══════════════════════════════════════════════════════════════

class SesionManager {
  static final SesionManager _instance = SesionManager._internal();
  factory SesionManager() => _instance;
  SesionManager._internal();

  String? _rutaActivaNombre;
  int? _ultimoSitioIndex;

  String? get rutaActivaNombre => _rutaActivaNombre;
  int? get ultimoSitioIndex => _ultimoSitioIndex;

  /// Carga la ruta activa guardada (llamar al iniciar la app)
  Future<void> cargarRutaActiva() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      _rutaActivaNombre = prefs.getString('sesion_ruta_activa');
      _ultimoSitioIndex = prefs.getInt('sesion_ultimo_sitio');
    } catch (e) {
      debugPrint('⚠️ Error cargando ruta activa: $e');
    }
  }

  /// Guarda la ruta que el usuario está realizando ahora.
  /// Llamar cuando el usuario abre/entra a una RouteDetailScreen.
  Future<void> setRutaActiva(String nombreRuta) async {
    _rutaActivaNombre = nombreRuta;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('sesion_ruta_activa', nombreRuta);
    } catch (e) {
      debugPrint('⚠️ Error guardando ruta activa: $e');
    }
  }

  /// Guarda el último sitio visto/validado (para retomar)
  Future<void> setUltimoSitio(int index) async {
    _ultimoSitioIndex = index;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setInt('sesion_ultimo_sitio', index);
    } catch (e) {
      debugPrint('⚠️ Error guardando último sitio: $e');
    }
  }

  /// Limpia la ruta activa (cuando el usuario completa la ruta o la abandona)
  Future<void> limpiarRutaActiva() async {
    _rutaActivaNombre = null;
    _ultimoSitioIndex = null;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.remove('sesion_ruta_activa');
      await prefs.remove('sesion_ultimo_sitio');
    } catch (e) {
      debugPrint('⚠️ Error limpiando ruta activa: $e');
    }
  }
}

// ═══════════════════════════════════════════════════════════════
//  NOTIFICATION MANAGER — Notificaciones locales
// ═══════════════════════════════════════════════════════════════
class NotificationManager {
  static final NotificationManager _instance = NotificationManager._internal();
  factory NotificationManager() => _instance;
  NotificationManager._internal();

  final FlutterLocalNotificationsPlugin _plugin = FlutterLocalNotificationsPlugin();
  bool _inicializado = false;

  Future<void> inicializar() async {
    if (_inicializado) return;
    try {
      tzdata.initializeTimeZones();
      // Zona horaria de Medellín
      tz.setLocalLocation(tz.getLocation('America/Bogota'));

      const androidInit = AndroidInitializationSettings('@mipmap/ic_launcher');
      const initSettings = InitializationSettings(android: androidInit);

      await _plugin.initialize(
        initSettings,
        onDidReceiveNotificationResponse: (response) {
          // Deep link desde notificación
          if (response.payload != null && response.payload!.isNotEmpty) {
            DeepLinkManager().procesarLink(response.payload!);
          }
        });

      // Solicitar permiso en Android 13+
      final androidPlugin = _plugin.resolvePlatformSpecificImplementation<
          AndroidFlutterLocalNotificationsPlugin>();
      await androidPlugin?.requestNotificationsPermission();

      _inicializado = true;
    } catch (e) {
      debugPrint('🔴 Error inicializando notificaciones: $e');
    }
  }

  /// Notificación inmediata simple
  Future<void> mostrar({
    required int id,
    required String titulo,
    required String mensaje,
    String? payload,
  }) async {
    if (!_inicializado) await inicializar();
    try {
      const androidDetails = AndroidNotificationDetails(
        'rutero_canal_general',
        'Rutero MDE',
        channelDescription: 'Notificaciones generales de Rutero MDE',
        importance: Importance.high,
        priority: Priority.high,
        icon: '@mipmap/ic_launcher',
      );
      const details = NotificationDetails(android: androidDetails);
      await _plugin.show(id, titulo, mensaje, details, payload: payload);
    } catch (e) {
      debugPrint('🔴 Error mostrando notificación: $e');
    }
  }

  /// Notificación programada a futuro (ej: recordatorio)
  Future<void> programar({
    required int id,
    required String titulo,
    required String mensaje,
    required DateTime cuando,
    String? payload,
  }) async {
    if (!_inicializado) await inicializar();
    try {
      const androidDetails = AndroidNotificationDetails(
        'rutero_canal_recordatorios',
        'Recordatorios Rutero MDE',
        channelDescription: 'Recordatorios de tus rutas compradas',
        importance: Importance.high,
        priority: Priority.high,
      );
      const details = NotificationDetails(android: androidDetails);
      await _plugin.zonedSchedule(
        id,
        titulo,
        mensaje,
        tz.TZDateTime.from(cuando, tz.local),
        details,
        payload: payload,
        androidScheduleMode: AndroidScheduleMode.inexactAllowWhileIdle,
        uiLocalNotificationDateInterpretation:
            UILocalNotificationDateInterpretation.absoluteTime);
    } catch (e) {
      debugPrint('🔴 Error programando notificación: $e');
    }
  }

  /// 🌹 Programa notificaciones de cuenta regresiva para Feria de las Flores
  /// Se llama una vez al iniciar la app — usa IDs fijos para no duplicar
  Future<void> programarFeria() async {
    if (!_inicializado) await inicializar();

    // Fecha inicio Feria de las Flores 2026
    final feria = DateTime(2026, 7, 31, 8, 0, 0);
    final ahora = DateTime.now();

    // Días antes de la feria en que se envía la notificación
    final recordatorios = [
      {'dias': 45, 'id': 4500, 'msg': '🌹 Faltan 45 días para la Feria de las Flores. ¡Marca tu calendario!'},
      {'dias': 30, 'id': 3000, 'msg': '🌸 Un mes para la Feria de las Flores. Edición 69 · ¡Entrada gratis!'},
      {'dias': 15, 'id': 1500, 'msg': '🌹 ¡15 días para la Feria! Prepara tu ruta en Rutero MDE.'},
      {'dias': 5,  'id': 500,  'msg': '🌸 ¡Solo 5 días para la Feria de las Flores! Todo listo en la app.'},
      {'dias': 3,  'id': 300,  'msg': '🌹 ¡3 días! La Feria de las Flores llega el 31 de julio. ¡No te la pierdas!'},
      {'dias': 1,  'id': 100,  'msg': '🌸 ¡Mañana empieza la Feria de las Flores! Abre Rutero MDE y empieza a explorar.'},
    ];

    for (final r in recordatorios) {
      final dias = r['dias'] as int;
      final id   = r['id'] as int;
      final msg  = r['msg'] as String;
      final cuando = feria.subtract(Duration(days: dias));

      // Solo programar si la fecha aún no pasó
      if (cuando.isAfter(ahora)) {
        await programar(
          id: id,
          titulo: '🌹 Feria de las Flores 2026',
          mensaje: msg,
          cuando: cuando,
          payload: 'feria_flores',
        );
        debugPrint('✅ Notificación Feria programada: $dias días antes → ${cuando.toIso8601String()}');
      }
    }
  }

  /// Cancela todas las notificaciones programadas
  Future<void> cancelarTodas() async {
    try {
      await _plugin.cancelAll();
    } catch (_) {}
  }

  // ── Notificaciones predefinidas de la app ──

  /// Al abrir la app después de X tiempo sin usar
  Future<void> bienvenidaDeVuelta() async {
    await mostrar(
      id: 100,
      titulo: t('🌿 ¡Bienvenido de vuelta!', '🌿 Welcome back!'),
      mensaje: t('Medellín te extraña. ¿Seguimos explorando?',
                 'Medellín misses you. Shall we keep exploring?'),
      payload: 'rutero://home',
    );
  }

  /// Al completar un sitio
  Future<void> sitioValidado(String sitioNombre, int completados, int total) async {
    final restantes = total - completados;
    await mostrar(
      id: 200 + completados,
      titulo: t('🎉 ¡Sitio validado!', '🎉 Spot validated!'),
      mensaje: restantes > 0
        ? t('$sitioNombre completado · Te quedan $restantes sitios',
            '$sitioNombre completed · $restantes spots remaining')
        : t('¡Completaste toda la ruta! Reclama tu insignia 🏆',
            'You finished the whole route! Claim your badge 🏆'),
      payload: 'rutero://home',
    );
  }

  /// Recordatorio de ruta comprada sin terminar (48h después)
  Future<void> programarRecordatorioRuta(String rutaNombre, String rutaId) async {
    final cuando = DateTime.now().add(const Duration(hours: 48));
    await programar(
      id: 300,
      titulo: t('🗺️ Tu ruta te espera', '🗺️ Your route is waiting'),
      mensaje: t('$rutaNombre · Retómala cuando quieras',
                 '$rutaNombre · Pick it up whenever you want'),
      cuando: cuando,
      payload: 'rutero://ruta/$rutaId',
    );
  }
}

// ═══════════════════════════════════════════════════════════════
//  DEEP LINK MANAGER — Enlaces profundos
// ═══════════════════════════════════════════════════════════════
// Formatos soportados:
//   rutero://ruta/NOMBRE_RUTA          → Abre detalle de ruta
//   rutero://logro/USUARIO/INSIGNIA    → Muestra logro público
//   rutero://perfil/USUARIO            → Perfil público con insignias
//   rutero://home                      → Home
// También acepta https://rutero.app/... con la misma estructura
class DeepLinkManager {
  static final DeepLinkManager _instance = DeepLinkManager._internal();
  factory DeepLinkManager() => _instance;
  DeepLinkManager._internal();

  final AppLinks _appLinks = AppLinks();
  StreamSubscription<Uri>? _sub;

  Future<void> inicializar() async {
    try {
      // 1) Capturar link que abrió la app
      final initialUri = await _appLinks.getInitialLink();
      if (initialUri != null) {
        Future.delayed(const Duration(milliseconds: 1500), () {
          procesarLink(initialUri.toString());
        });
      }
      // 2) Escuchar links mientras la app está abierta
      _sub = _appLinks.uriLinkStream.listen((uri) {
        procesarLink(uri.toString());
      });
    } catch (e) {
      debugPrint('🔴 Error inicializando deep links: $e');
    }
  }

  void procesarLink(String link) {
    try {
      final uri = Uri.parse(link);
      final segments = uri.pathSegments;
      // Detectar host o primer segmento como tipo
      final tipo = uri.host.isNotEmpty ? uri.host : (segments.isNotEmpty ? segments[0] : '');


      final ctx = kNavKey.currentContext;
      if (ctx == null) return;

      if (tipo == 'ruta' && segments.isNotEmpty) {
        final rutaNombre = Uri.decodeComponent(segments.last);
        _abrirRuta(ctx, rutaNombre);
      } else if (tipo == 'logro' && segments.length >= 2) {
        final usuario = Uri.decodeComponent(segments[segments.length - 2]);
        final insignia = Uri.decodeComponent(segments.last);
        _mostrarLogro(ctx, usuario, insignia);
      } else if (tipo == 'perfil' && segments.isNotEmpty) {
        final usuario = Uri.decodeComponent(segments.last);
        _abrirPerfilPublico(ctx, usuario);
      }
    } catch (e) {
      debugPrint('🔴 Error procesando deep link: $e');
    }
  }

  void _abrirRuta(BuildContext ctx, String rutaNombre) {
    // Busca la ruta por nombre (case-insensitive)
    final normalizado = rutaNombre.toUpperCase().replaceAll('_', ' ').replaceAll('-', ' ');
    final ruta = RutasService().rutas.firstWhere(
      (r) {
        final n = r['nombre'].toString().toUpperCase();
        return n == normalizado || n.contains(normalizado) || normalizado.contains(n);
      },
      orElse: () => <String, dynamic>{});
    if (ruta.isEmpty) return;
    Navigator.of(ctx, rootNavigator: true).push(MaterialPageRoute(
      builder: (_) => RouteDetailScreen(ruta: ruta)));
  }

  void _mostrarLogro(BuildContext ctx, String usuario, String insignia) {
    Navigator.of(ctx, rootNavigator: true).push(MaterialPageRoute(
      builder: (_) => LogroPublicoScreen(usuario: usuario, insignia: insignia)));
  }

  void _abrirPerfilPublico(BuildContext ctx, String usuario) {
    Navigator.of(ctx, rootNavigator: true).push(MaterialPageRoute(
      builder: (_) => PerfilPublicoScreen(usuario: usuario)));
  }

  /// Genera un link compartible para una ruta
  static String linkRuta(String rutaNombre) {
    final slug = rutaNombre.replaceAll(' ', '_').toUpperCase();
    return 'https://rutero.app/ruta/$slug';
  }

  /// Genera un link compartible para un logro
  static String linkLogro(String usuario, String insignia) {
    final u = Uri.encodeComponent(usuario);
    final i = Uri.encodeComponent(insignia);
    return 'https://rutero.app/logro/$u/$i';
  }

  /// Genera un link compartible para un perfil público
  static String linkPerfil(String usuario) {
    // 🚧 Beta: dominio rutero.app pendiente — usar landing actual
    return 'https://rutero-mde.web.app';
  }

  void dispose() {
    _sub?.cancel();
  }
}

