  final String taglineES;   // Tagline en español
  final String taglineEN;   // Tagline en inglés
  final String nombreApp;   // Nombre de la app en esa ciudad
  const _CiudadRegistrada({
    required this.ciudad, required this.pais,
    required this.lat, required this.lng,
    this.radioKm = 35,
    required this.codigo,
    required this.emoji,
    required this.taglineES,
    required this.taglineEN,
    required this.nombreApp,
  });
}

