/// Carga el estado del modo demo desde SharedPreferences (persistente)
Future<void> cargarModoDemo() async {
  try {
    final prefs = await SharedPreferences.getInstance();
    // Cargar estado real del modo demo
    final demo = prefs.getBool('modo_demo_admin') ?? false;
    kModoDemoNotifier.value = demo;
  } catch (e) {
    debugPrint('⚠️ Error cargando modo demo: $e');
  }
}

/// Alterna el modo demo y lo guarda en SharedPreferences
Future<void> toggleModoDemo() async {
  try {
    kModoDemoNotifier.value = !kModoDemoNotifier.value;
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool('modo_demo_admin', kModoDemoNotifier.value);
  } catch (e) {
    debugPrint('⚠️ Error guardando modo demo: $e');
  }
}
