// ─────────────────────────────────────────
//  MONEDA — COP para Colombia, USD para el resto
// ─────────────────────────────────────────
// Detección automática por locale del dispositivo.
// Se puede sobreescribir manualmente desde el perfil.
// null = auto-detectar, 'COP' = forzar pesos, 'USD' = forzar dólares
final ValueNotifier<String?> monedaOverride = ValueNotifier<String?>(null);

// Tasa de conversión (se puede actualizar en Firestore sin re-compilar)
const double kTasaCopUsd = 4000.0; // 1 USD = 4.000 COP aprox
const double kMultiplicadorTurista = 1.8; // precio turista = precio local × 1.8

bool get esTurista {
  if (monedaOverride.value == 'COP') return false;
  if (monedaOverride.value == 'USD') return true;
  // Auto-detección: si el país del celular NO es CO → turista
  final country = WidgetsBinding.instance.platformDispatcher.locale.countryCode;
  return country != 'CO';
}

String get monedaActiva => esTurista ? 'USD' : 'COP';

// Convierte un precio string tipo "$19.900" al formato correcto según moneda
String precioMostrado(dynamic precioOriginal) {
  if (precioOriginal == null) return '';
  final String s = precioOriginal.toString();
  // Extrae el número del string (ej: "$19.900" → 19900)
  final cleaned = s.replaceAll(RegExp(r'[^0-9]'), '');
  if (cleaned.isEmpty) return s;
  final int copValue = int.tryParse(cleaned) ?? 0;
  if (copValue == 0) return s;

  if (!esTurista) {
    // Local → mostrar tal cual con formato COP
    return '\$${_formatCop(copValue)}';
  }
  // Turista → aplicar multiplicador y convertir a USD
  final double usdValue = (copValue * kMultiplicadorTurista) / kTasaCopUsd;
  return '\$${_formatUsd(usdValue)} USD';
}

String _formatCop(int value) {
  // 19900 → "19.900"
  final s = value.toString();
  final buf = StringBuffer();
  for (int i = 0; i < s.length; i++) {
    if (i > 0 && (s.length - i) % 3 == 0) buf.write('.');
    buf.write(s[i]);
  }
  return buf.toString();
}

String _formatUsd(double value) {
  // Redondea a .99 para marketing
  final int entero = value.floor();
  return '$entero.99';
}

