// ── Helpers para nombre/subtítulo de rutas según idioma ──
String rNombre(Map<String, dynamic> r)   => (kLang == 'en' ? r['nombreEN'] : null) ?? r['nombre'] ?? '';
String rSubtitulo(Map<String, dynamic> r) => (kLang == 'en' ? r['subtituloEN'] : null) ?? r['subtitulo'] ?? '';

// ── Traducir dificultad ──
String _tDificultad(String d) {
  if (d == 'FÁCIL')  return t('FÁCIL', 'EASY');
  if (d == 'MEDIO')  return t('MEDIO', 'MEDIUM');
  if (d == 'DIFÍCIL') return t('DIFÍCIL', 'HARD');
  return d;
}

