// ─────────────────────────────────────────
//  RUTERO NAV — Transiciones cinematográficas
// ─────────────────────────────────────────
class RuteroNav {
  static Future<T?> push<T>(BuildContext context, Widget screen) {
    return Navigator.of(context).push<T>(PageRouteBuilder(
      pageBuilder: (_, __, ___) => screen,
      transitionDuration: const Duration(milliseconds: 400),
      reverseTransitionDuration: const Duration(milliseconds: 300),
      transitionsBuilder: (_, animation, __, child) {
        final tween = Tween(begin: const Offset(0, 0.08), end: Offset.zero)
          .chain(CurveTween(curve: Curves.easeOutCubic));
        return FadeTransition(
          opacity: CurvedAnimation(parent: animation, curve: Curves.easeOut),
          child: SlideTransition(position: animation.drive(tween), child: child));
      }));
  }
}

// ─────────────────────────────────────────
//  MAIN SHELL — Navegación global persistente
// ─────────────────────────────────────────
class MainShell extends StatefulWidget {
  const MainShell({super.key});
  @override
  State<MainShell> createState() => _MainShellState();
}

class _MainShellState extends State<MainShell> {
  int _currentTab = 0;
  final List<GlobalKey<NavigatorState>> _navKeys = [
    GlobalKey<NavigatorState>(),
    GlobalKey<NavigatorState>(),
    GlobalKey<NavigatorState>(),
    GlobalKey<NavigatorState>(),
    GlobalKey<NavigatorState>(),
  ];

  void _onTabNotifier() {
    if (mounted) setState(() => _currentTab = tabNotifier.value);
  }

  @override
  void initState() {
    super.initState();
    AudioManager().iniciarMusicaPrincipal();
    // Escuchar cambios de tab desde cualquier widget via tabNotifier
    tabNotifier.addListener(_onTabNotifier);
    // Notificación de bienvenida al abrir la app (después de 3 segundos)
    Future.delayed(const Duration(seconds: 3), () {
      NotificationManager().bienvenidaDeVuelta();
    });
    // 🗺️ Si el usuario tenía una ruta activa, restaurarla automáticamente.
    // Resuelve: cuando el usuario cierra la app por seguridad o accidente,
    // al volver a abrirla no debe perder el contexto de la ruta que hacía.
    WidgetsBinding.instance.addPostFrameCallback((_) => _restaurarRutaActiva());
  }

  /// Si hay una ruta activa guardada, navega automáticamente a ella
  /// con el progreso restaurado. El usuario puede salir si no quiere continuarla.
  void _restaurarRutaActiva() {
    final nombreRuta = SesionManager().rutaActivaNombre;
    if (nombreRuta == null || nombreRuta.isEmpty) return;

    // Buscar la ruta en el listado global
    final ruta = RutasService().rutas.firstWhere(
      (r) => r['nombre'] == nombreRuta,
      orElse: () => <String, dynamic>{});
    if (ruta.isEmpty) {
      // FIX (19/05/2026): Ruta guardada ya no existe — limpiar sesión huérfana
      SesionManager().limpiarRutaActiva();
      return;
    }

    final totalSitios = (ruta['sitiosList'] as List?)?.length ?? 0;
    final progreso = SesionManager().ultimoSitioIndex ?? 0;

    // FIX (19/05/2026): Validar que el índice guardado sea coherente con
    // el total real de sitios de la ruta. Si el índice >= total, significa
    // que la ruta ya fue completada o el dato está corrupto — limpiar y no restaurar.
    // Esto previene el bug donde sitios se marcan como visitados al abrir la app
    // sin haber estado en el lugar (índice de otra sesión aplicado incorrectamente).
    if (progreso <= 0 || progreso >= totalSitios) {
      SesionManager().limpiarRutaActiva();
      return;
    }

    // Navegar a la pantalla de detalle de ruta usando el navegador del tab Home
    _navKeys[0].currentState?.push(
      MaterialPageRoute(builder: (_) => RouteDetailScreen(
        ruta: ruta,
        progresoInicial: progreso,
      )),
    );
  }

  @override
  void dispose() {
    tabNotifier.removeListener(_onTabNotifier);
    AudioManager().dispose();
    super.dispose();
  }

  Future<bool> _onWillPop() async {
    final canPop = _navKeys[_currentTab].currentState?.canPop() ?? false;
    if (canPop) {
      _navKeys[_currentTab].currentState?.pop();
      return false;
    }
    return true;
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<String>(
      valueListenable: langNotifier,
      builder: (context, lang, _) => WillPopScope(
        onWillPop: _onWillPop,
        child: Scaffold(
          resizeToAvoidBottomInset: false,
          body: StreamBuilder(
            stream: FirebaseAuth.instance.authStateChanges(),
            builder: (context, authSnap) => ValueListenableBuilder<String>(
            valueListenable: langNotifier,
            builder: (_, __, ___) {
              // Durante pre-feria y feria (19 jul – 9 ago): Feria va primero
              // Admin siempre ve Feria (feriaModuloActivo retorna true para admin)
              final feria = feriaModuloActivo;
              final screens = feria ? [
                Navigator(
                  key: _navKeys[4],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => const FeriaScreen()),
                ),
                Navigator(
                  key: _navKeys[0],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => HomeBody(
                      onTabChange: (i) => tabNotifier.value = i)),
                ),
                Navigator(
                  key: _navKeys[1],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => const MapScreen()),
                ),
                Navigator(
                  key: _navKeys[2],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => const AchievementsScreen()),
                ),
                Navigator(
                  key: _navKeys[3],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => const ProfileScreen()),
                ),
              ] : [
                Navigator(
                  key: _navKeys[0],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => HomeBody(
                      onTabChange: (i) => tabNotifier.value = i)),
                ),
                Navigator(
                  key: _navKeys[1],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => const MapScreen()),
                ),
                Navigator(
                  key: _navKeys[2],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => const AchievementsScreen()),
                ),
                Navigator(
                  key: _navKeys[3],
                  onGenerateRoute: (settings) => MaterialPageRoute(
                    builder: (_) => const ProfileScreen()),
                ),
              ];
              return IndexedStack(index: _currentTab, children: screens);
            },
          ),
          ),
          bottomNavigationBar: _BottomNav(
            currentIndex: _currentTab,
            onTap: (i) => setState(() => _currentTab = i),
            feriaActiva: feriaModuloActivo,
          ),
          floatingActionButton: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              // 🔊 Botón de audio — discreto, estilo marca de agua
              _AudioFloatingButton(),
              const SizedBox(height: 8),
              _SOSFloatingButton(),
            ],
          ),
        ),
      ),
    );
  }
}

