// ─────────────────────────────────────────
//  ONBOARDING — Solo primera vez (persistente)
// ─────────────────────────────────────────
// Flag en memoria para la sesión actual
bool _onboardingVisto = false;

bool _checkOnboardingVisto() => _onboardingVisto;

void _marcarOnboardingVisto() { _onboardingVisto = true; }

class OnboardingScreen extends StatefulWidget {
  const OnboardingScreen({super.key});
  @override
  State<OnboardingScreen> createState() => _OnboardingScreenState();
}

class _OnboardingScreenState extends State<OnboardingScreen>
    with TickerProviderStateMixin {
  final PageController _pageCtrl = PageController();
  int _paginaActual = 0;
  late AnimationController _floatCtrl;
  late AnimationController _pulseCtrl;
  late AnimationController _slideCtrl;
  late Animation<double> _floatAnim;
  late Animation<double> _pulseAnim;
  late Animation<double> _slideAnim;
  late Animation<double> _fadeAnim;

  final List<Map<String, dynamic>> _slides = [
    {
      'emoji': '🗺️',
      'emojisBg': ['🏙️', '🌳', '🚇', '🎨', '📍'],
      'titulo': 'Explora Medellín\ncomo nunca antes',
      'tituloEN': 'Explore Medellín\nlike never before',
      'desc': 'Más de 32 rutas gamificadas por la ciudad de la eterna primavera. Cada sitio tiene su historia — tú la descubres.',
      'descEN': 'Over 32 gamified routes through the city of eternal spring. Every spot has its story — you discover it.',
      'color1': 0xFF5BAD6F,
      'color2': 0xFF1B5E3A,
      'imagen': 'assets/images/onboarding_explora.png',
      'tag1': '32+ rutas', 'tag1EN': '32+ routes',
      'tag2': '155+ sitios', 'tag2EN': '155+ spots',
    },
    {
      'emoji': '📸',
      'emojisBg': ['✨', '📍', '🎯', '🔓', '⭐'],
      'titulo': 'Valida tu visita\ncon una foto',
      'tituloEN': 'Validate your visit\nwith a photo',
      'desc': 'Llega al sitio, toma la foto y gana puntos reales. El GPS confirma que estás ahí — cero trampa, pura aventura.',
      'descEN': 'Get to the spot, take the photo and earn real points. GPS confirms you are there — no cheating, pure adventure.',
      'color1': 0xFFE9B949,
      'color2': 0xFF8B6914,
      'imagen': 'assets/images/onboarding_valida.png',
      'tag1': 'GPS verificado', 'tag1EN': 'GPS verified',
      'tag2': '+30 puntos', 'tag2EN': '+30 points',
    },
    {
      'emoji': '🏆',
      'emojisBg': ['🎖️', '💎', '🎁', '🌟', '👑'],
      'titulo': 'Gana insignias\ny premios reales',
      'tituloEN': 'Earn badges\nand real rewards',
      'desc': 'Desbloquea insignias coleccionables, descuentos en aliados y experiencias exclusivas en Medellín.',
      'descEN': 'Unlock collectible badges, discounts at partners and exclusive experiences in Medellín.',
      'color1': 0xFFB85CAE,
      'color2': 0xFF5A1B55,
      'imagen': 'assets/images/onboarding_gana.png',
      'tag1': 'Insignias', 'tag1EN': 'Badges',
      'tag2': 'Descuentos', 'tag2EN': 'Discounts',
    },
  ];

  @override
  void initState() {
    super.initState();
    _floatCtrl = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 3000))..repeat(reverse: true);
    _pulseCtrl = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 1400))..repeat(reverse: true);
    _slideCtrl = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 600));
    _floatAnim = Tween<double>(begin: -8.0, end: 8.0)
      .animate(CurvedAnimation(parent: _floatCtrl, curve: Curves.easeInOut));
    _pulseAnim = Tween<double>(begin: 0.95, end: 1.08)
      .animate(CurvedAnimation(parent: _pulseCtrl, curve: Curves.easeInOut));
    _slideAnim = Tween<double>(begin: 40.0, end: 0.0)
      .animate(CurvedAnimation(parent: _slideCtrl, curve: Curves.easeOutCubic));
    _fadeAnim = Tween<double>(begin: 0.0, end: 1.0)
      .animate(CurvedAnimation(parent: _slideCtrl, curve: Curves.easeOut));
    _slideCtrl.forward();
  }

  void _siguiente() {
    if (_paginaActual < _slides.length - 1) {
      _pageCtrl.nextPage(
        duration: const Duration(milliseconds: 500),
        curve: Curves.easeInOutCubic);
    } else {
      _terminar();
    }
  }

  void _terminar() {
    _marcarOnboardingVisto();
    if (!mounted) return;
    // FIX 30/06/2026: se elimina BetaWelcomeScreen del flujo — va directo a login.
    Navigator.of(context).pushReplacement(PageRouteBuilder(
      pageBuilder: (_, __, ___) => const WelcomeScreen(),
      transitionsBuilder: (_, anim, __, child) =>
          FadeTransition(opacity: anim, child: child),
      transitionDuration: const Duration(milliseconds: 500),
    ));
  }

  @override
  void dispose() {
    _pageCtrl.dispose();
    _floatCtrl.dispose();
    _pulseCtrl.dispose();
    _slideCtrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final slide = _slides[_paginaActual];
    final Color color1 = Color(slide['color1'] as int);
    final Color color2 = Color(slide['color2'] as int);

    return Scaffold(
      body: AnimatedContainer(
        duration: const Duration(milliseconds: 600),
        curve: Curves.easeInOut,
        decoration: const BoxDecoration(color: Colors.black),
        child: Stack(children: [
          // Imagen de fondo
          Positioned.fill(
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 600),
              child: Image.asset(
                slide['imagen'] as String,
                key: ValueKey(slide['imagen']),
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) =>
                  CustomPaint(painter: _LeafPatternPainter())))),
          // Overlay
          Positioned.fill(child: Container(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter, end: Alignment.bottomCenter,
                stops: const [0.0, 0.4, 0.75, 1.0],
                colors: [
                  Colors.black.withOpacity(0.30),
                  Colors.black.withOpacity(0.10),
                  Colors.black.withOpacity(0.50),
                  Colors.black.withOpacity(0.92),
                ])))),

          // Emojis flotantes
          ...List.generate(5, (i) {
            final emojisBg = slide['emojisBg'] as List;
            return AnimatedBuilder(
              animation: _floatAnim,
              builder: (_, __) {
                final posX = [0.1, 0.8, 0.15, 0.75, 0.5][i];
                final posY = [0.15, 0.25, 0.55, 0.6, 0.35][i];
                return Positioned(
                  left: MediaQuery.of(context).size.width * posX,
                  top: MediaQuery.of(context).size.height * posY +
                    _floatAnim.value * (i.isEven ? 1 : -1),
                  child: Opacity(opacity: 0.07,
                    child: Text(emojisBg[i % emojisBg.length],
                      style: const TextStyle(fontSize: 38))));
              });
          }),

          SafeArea(child: Column(children: [
            // Header: indicadores + skip
            Padding(
              padding: const EdgeInsets.fromLTRB(24, 16, 20, 0),
              child: Row(children: [
                Expanded(child: Row(children: List.generate(_slides.length, (i) {
                  final activo = i == _paginaActual;
                  return AnimatedContainer(
                    duration: const Duration(milliseconds: 400),
                    margin: const EdgeInsets.only(right: 6),
                    height: 6, width: activo ? 36 : 6,
                    decoration: BoxDecoration(
                      color: activo ? Colors.white : Colors.white.withOpacity(0.25),
                      borderRadius: BorderRadius.circular(3),
                      boxShadow: activo ? [BoxShadow(
                        color: Colors.white.withOpacity(0.5), blurRadius: 8)] : null));
                }))),
                GestureDetector(
                  onTap: _terminar,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 7),
                    decoration: BoxDecoration(
                      color: Colors.white.withOpacity(0.12),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: Colors.white.withOpacity(0.2))),
                    child: Text(t('Saltar', 'Skip'),
                      style: const TextStyle(color: Colors.white,
                        fontSize: 12, fontWeight: FontWeight.w600)))),
              ])),

            // Slides
            Expanded(child: PageView.builder(
              controller: _pageCtrl,
              onPageChanged: (i) {
                setState(() => _paginaActual = i);
                _slideCtrl.reset();
                _slideCtrl.forward();
              },
              itemCount: _slides.length,
              itemBuilder: (_, i) {
                final s = _slides[i];
                final Color c1 = Color(s['color1'] as int);
                return Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 24),
                  child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                    // Emoji con halo pulsante
                    AnimatedBuilder(
                      animation: _pulseAnim,
                      builder: (_, __) => Transform.scale(
                        scale: i == _paginaActual ? _pulseAnim.value : 1.0,
                        child: Container(width: 160, height: 160,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            gradient: RadialGradient(colors: [
                              c1.withOpacity(0.4),
                              c1.withOpacity(0.15),
                              Colors.transparent,
                            ]),
                            boxShadow: [BoxShadow(color: c1.withOpacity(0.5),
                              blurRadius: 50, spreadRadius: 10)]),
                          child: Center(child: Text(s['emoji'] as String,
                            style: const TextStyle(fontSize: 84)))))),
                    const SizedBox(height: 36),

                    // Card con animación fade+slide
                    AnimatedBuilder(
                      animation: _slideCtrl,
                      builder: (_, child) => i == _paginaActual
                        ? Transform.translate(
                            offset: Offset(0, _slideAnim.value),
                            child: Opacity(opacity: _fadeAnim.value, child: child))
                        : child!,
                      child: Container(
                        padding: const EdgeInsets.all(24),
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.07),
                          borderRadius: BorderRadius.circular(24),
                          border: Border.all(
                            color: Colors.white.withOpacity(0.15), width: 1.5),
                          boxShadow: [BoxShadow(
                            color: c1.withOpacity(0.2),
                            blurRadius: 30, offset: const Offset(0, 10))]),
                        child: Column(children: [
                          // Título en PlayfairDisplay
                          Text(
                            kLang == 'en' ? s['tituloEN'] as String : s['titulo'] as String,
                            textAlign: TextAlign.center,
                            style: TextStyle(
                              fontFamily: 'PlayfairDisplay',
                              fontSize: 26, fontWeight: FontWeight.w900,
                              color: Colors.white, height: 1.2,
                              shadows: [Shadow(color: c1.withOpacity(0.8),
                                blurRadius: 20)])),
                          const SizedBox(height: 14),
                          Text(
                            kLang == 'en' ? s['descEN'] as String : s['desc'] as String,
                            textAlign: TextAlign.center,
                            style: TextStyle(
                              fontFamily: 'Inter',
                              fontSize: 14,
                              color: Colors.white.withOpacity(0.85),
                              height: 1.6)),
                          const SizedBox(height: 18),
                          Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                            _OnbTag(label: kLang == 'en'
                              ? s['tag1EN'] as String : s['tag1'] as String, color: c1),
                            const SizedBox(width: 10),
                            _OnbTag(label: kLang == 'en'
                              ? s['tag2EN'] as String : s['tag2'] as String, color: c1),
                          ]),
                        ])),
                    ),
                  ]));
              })),

            // Botón
            Padding(
              padding: const EdgeInsets.fromLTRB(24, 0, 24, 32),
              child: GestureDetector(
                onTap: _siguiente,
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 400),
                  width: double.infinity,
                  padding: const EdgeInsets.symmetric(vertical: 18),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(colors: [color1, color2]),
                    borderRadius: BorderRadius.circular(18),
                    boxShadow: [BoxShadow(
                      color: color1.withOpacity(0.55),
                      blurRadius: 25, offset: const Offset(0, 10))]),
                  child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                    Text(
                      _paginaActual < _slides.length - 1
                        ? t('SIGUIENTE', 'NEXT')
                        : t('¡EMPEZAR A EXPLORAR!', 'START EXPLORING!'),
                      textAlign: TextAlign.center,
                      style: const TextStyle(
                        fontFamily: 'Inter',
                        fontSize: 15, fontWeight: FontWeight.w900,
                        color: Colors.white, letterSpacing: 1.5)),
                    const SizedBox(width: 8),
                    Text(_paginaActual < _slides.length - 1 ? '→' : '🚀',
                      style: const TextStyle(fontSize: 18, color: Colors.white)),
                  ])))),
          ])),
        ])),
    );
  }
}


class _OnbTag extends StatelessWidget {
  final String label;
  final Color color;
  const _OnbTag({required this.label, required this.color});
  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
      decoration: BoxDecoration(
        color: color.withOpacity(0.2),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: color.withOpacity(0.5))),
      child: Text(label, style: TextStyle(
        fontSize: 11, fontWeight: FontWeight.w700, color: Colors.white,
        letterSpacing: 0.5)));
  }
}


// ═══════════════════════════════════════════════════════════════════════════
//  🌿 WELCOME SCREEN
//  Pantalla informativa de primera apertura — lanzamiento oficial
// ═══════════════════════════════════════════════════════════════════════════
class BetaWelcomeScreen extends StatefulWidget {
  const BetaWelcomeScreen({super.key});
  @override
  State<BetaWelcomeScreen> createState() => _BetaWelcomeScreenState();
}

class _BetaWelcomeScreenState extends State<BetaWelcomeScreen>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<double> _fadeAnim;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 800));
    _fadeAnim = CurvedAnimation(parent: _ctrl, curve: Curves.easeIn);
    _ctrl.forward();
  }

  @override
  void dispose() { _ctrl.dispose(); super.dispose(); }

  void _continuar() => Navigator.of(context).pushReplacement(
    PageRouteBuilder(
      pageBuilder: (_, __, ___) => const WelcomeScreen(),
      transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
      transitionDuration: const Duration(milliseconds: 600)));

  @override
  Widget build(BuildContext context) {
    // FIX 30/06/2026: en Android 15 con barra de navegación de 3 botones,
    // el sistema a veces fuerza modo edge-to-edge y MediaQuery no reporta
    // bien el inset inferior, dejando el botón "Empezar a explorar" tapado
    // y sin scroll disponible para alcanzarlo. Forzamos un padding inferior
    // mínimo adicional (24px + el inset real del sistema, con un piso de 32px)
    // para garantizar que SIEMPRE haya espacio scrolleable debajo del botón.
    final double insetInferior = MediaQuery.of(context).padding.bottom;
    final double paddingInferiorSeguro = (insetInferior < 32 ? 32 : insetInferior) + 24;

    return Scaffold(
    backgroundColor: kDark,
    body: FadeTransition(opacity: _fadeAnim, child: SafeArea(
      child: SingleChildScrollView(
        padding: EdgeInsets.fromLTRB(28, 24, 28, paddingInferiorSeguro),
        child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
            decoration: BoxDecoration(
              color: kGold.withOpacity(0.12), borderRadius: BorderRadius.circular(20),
              border: Border.all(color: kGold.withOpacity(0.4))),
            child: Text(t('🌿 ACCESO GRATUITO · Lanzamiento oficial', '🌿 FREE ACCESS · Official launch'),
              style: TextStyle(color: kGold, fontSize: 11, fontWeight: FontWeight.w700, letterSpacing: 1))),
          const SizedBox(height: 32),
          const Text('🌿', style: TextStyle(fontSize: 64)),
          const SizedBox(height: 20),
          Text(t('Bienvenido a Rutero MDE', 'Welcome to Rutero MDE'),
            style: const TextStyle(color: kText, fontSize: 26, fontWeight: FontWeight.w900),
            textAlign: TextAlign.center),
          const SizedBox(height: 12),
          Text(
            t('Explora Medellín con rutas GPS, gana insignias y desbloquea recompensas reales en negocios locales.',
              'Explore Medellín with GPS routes, earn badges and unlock real rewards at local businesses.'),
            style: const TextStyle(color: kTextMuted, fontSize: 14, height: 1.6),
            textAlign: TextAlign.center),
          const SizedBox(height: 32),
          _BetaChip(emoji: '🎁', texto: t('Todas las rutas disponibles de forma gratuita', 'All routes available for free')),
          const SizedBox(height: 10),
          _BetaChip(emoji: '📍', texto: t('GPS real en cada sitio del recorrido', 'Real GPS at every route stop')),
          const SizedBox(height: 10),
          _BetaChip(emoji: '💬', texto: t('Comparte tu opinión desde tu perfil', 'Share feedback from your profile')),
          const SizedBox(height: 10),
          _BetaChip(emoji: '🏅', texto: t('Colecciona insignias al completar rutas', 'Collect badges as you complete routes')),
          const SizedBox(height: 40),
          GestureDetector(
            onTap: _continuar,
            child: Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(vertical: 16),
              decoration: BoxDecoration(
                gradient: LinearGradient(colors: [kGreen, kGreen.withOpacity(0.7)]),
                borderRadius: BorderRadius.circular(16)),
              child: Text(t('¡Empezar a explorar!', 'Start exploring!'),
                style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.w900),
                textAlign: TextAlign.center))),
          const SizedBox(height: 16),
          // Badge Créame — Alcaldía de Medellín
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
            decoration: BoxDecoration(
              color: const Color(0xFF0A1628),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: const Color(0xFF1E3A5F), width: 1),
              boxShadow: [BoxShadow(
                color: const Color(0xFF1E3A5F).withOpacity(0.3),
                blurRadius: 12)]),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              // Escudo minimalista
              Container(width: 32, height: 32,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  gradient: const LinearGradient(
                    colors: [Color(0xFF1565C0), Color(0xFF0D47A1)],
                    begin: Alignment.topLeft, end: Alignment.bottomRight),
                  boxShadow: [BoxShadow(
                    color: const Color(0xFF1565C0).withOpacity(0.4),
                    blurRadius: 8)]),
                child: const Center(child: Text('🏛️',
                  style: TextStyle(fontSize: 16)))),
              const SizedBox(width: 10),
              Column(crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min, children: [
                const Text('Proyecto beneficiario',
                  style: TextStyle(
                    color: Color(0xFF90CAF9),
                    fontSize: 9, letterSpacing: 0.5)),
                const Text('Programa Créame',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 11, fontWeight: FontWeight.w800,
                    letterSpacing: 0.3)),
                const Text('Alcaldía de Medellín · 2025',
                  style: TextStyle(
                    color: Color(0xFF90CAF9),
                    fontSize: 9, letterSpacing: 0.3)),
              ]),
            ])),
          ]),
        ),
      ),
    ),
  );
  }
}

class _BetaChip extends StatelessWidget {
  final String emoji;
  final String texto;
  const _BetaChip({required this.emoji, required this.texto});
  @override
  Widget build(BuildContext context) => Container(
    width: double.infinity,
    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
    decoration: BoxDecoration(
      color: kDark2, borderRadius: BorderRadius.circular(12),
      border: Border.all(color: kGreen.withOpacity(0.2))),
    child: Row(children: [
      Text(emoji, style: const TextStyle(fontSize: 16)),
