// ─────────────────────────────────────────────────────────────────────────
//  PANTALLA — Moneda + Jerga Paisa
// ─────────────────────────────────────────────────────────────────────────
class MonedaYJergaScreen extends StatefulWidget {
  const MonedaYJergaScreen({super.key});
  @override
  State<MonedaYJergaScreen> createState() => _MonedaYJergaScreenState();
}

class _MonedaYJergaScreenState extends State<MonedaYJergaScreen> {
  double? _tasaUsdCop;
  bool _cargando = true;
  bool _esOffline = false;
  final TextEditingController _usdCtrl = TextEditingController(text: '1');
  double _copResultado = 0;
  Set<String> _palabrasAprendidas = {};

  @override
  void initState() {
    super.initState();
    _cargarTasa();
    _cargarPalabrasAprendidas();
  }

  Future<void> _cargarPalabrasAprendidas() async {
    final prefs = await SharedPreferences.getInstance();
    final lista = prefs.getStringList('palabras_paisa_aprendidas') ?? [];
    if (mounted) setState(() => _palabrasAprendidas = lista.toSet());
  }

  Future<void> _marcarAprendida(String palabra) async {
    final prefs = await SharedPreferences.getInstance();
    _palabrasAprendidas.add(palabra);
    await prefs.setStringList('palabras_paisa_aprendidas', _palabrasAprendidas.toList());
    if (mounted) setState(() {});
  }

  Future<void> _cargarTasa() async {
    final prefs = await SharedPreferences.getInstance();
    try {
      final response = await http
        .get(Uri.parse('https://open.er-api.com/v6/latest/USD'))
        .timeout(const Duration(seconds: 6));
      if (response.statusCode == 200) {
        final data = json.decode(response.body);
        final tasa = (data['rates']?['COP'] as num?)?.toDouble();
        if (tasa != null) {
          await prefs.setDouble('tasa_usd_cop_cache', tasa);
          await prefs.setString('tasa_usd_cop_fecha', DateTime.now().toIso8601String());
          if (mounted) setState(() {
            _tasaUsdCop = tasa;
            _cargando = false;
            _esOffline = false;
            _recalcular();
          });
          return;
        }
      }
      throw Exception('Respuesta inválida');
    } catch (e) {
      debugPrint('⚠️ Error obteniendo tasa USD/COP: $e');
      final cache = prefs.getDouble('tasa_usd_cop_cache');
      if (mounted) setState(() {
        _tasaUsdCop = cache;
        _cargando = false;
        _esOffline = true;
        _recalcular();
      });
    }
  }

  void _recalcular() {
    final usd = double.tryParse(_usdCtrl.text.replaceAll(',', '.')) ?? 0;
    setState(() => _copResultado = usd * (_tasaUsdCop ?? 0));
  }

  String _formatoCop(double v) {
    final s = v.round().toString();
    final buf = StringBuffer();
    for (int i = 0; i < s.length; i++) {
      if (i > 0 && (s.length - i) % 3 == 0) buf.write('.');
      buf.write(s[i]);
    }
    return '\$$buf';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kDark2,
      body: Column(children: [
        Container(
          decoration: BoxDecoration(
            color: kDark2,
            border: Border(bottom: BorderSide(color: kGold.withOpacity(0.1)))),
          child: SafeArea(bottom: false, child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 20, 18),
            child: Row(children: [
              GestureDetector(onTap: () => Navigator.pop(context),
                child: Container(width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.06),
                    shape: BoxShape.circle,
                    border: Border.all(color: kGold.withOpacity(0.2))),
                  child: const Center(child: Text('←',
                    style: TextStyle(color: kText, fontSize: 16))))),
              const SizedBox(width: 12),
              Expanded(child: Text(t('Moneda y jerga paisa','Currency & paisa slang'),
                style: const TextStyle(
                  fontFamily: 'PlayfairDisplay',
                  fontSize: 18, fontWeight: FontWeight.w900,
                  color: kText, letterSpacing: 0.2))),
              const Text('💱', style: TextStyle(fontSize: 20)),
            ])))),
        Expanded(child: ListView(
          padding: const EdgeInsets.fromLTRB(20, 16, 20, 40),
          children: [
            Text(t('Conversor USD → COP','USD → COP Converter'),
              style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w900,
                color: kTextMuted, letterSpacing: 1.5)),
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(16),
                border: Border.all(color: kGold.withOpacity(0.25))),
              child: _cargando
                ? const Center(child: Padding(
                    padding: EdgeInsets.symmetric(vertical: 12),
                    child: CircularProgressIndicator(color: kGold, strokeWidth: 2)))
                : Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Row(children: [
                      Expanded(child: TextField(
                        controller: _usdCtrl,
                        keyboardType: const TextInputType.numberWithOptions(decimal: true),
                        style: const TextStyle(color: kText, fontSize: 22, fontWeight: FontWeight.w700),
                        decoration: const InputDecoration(
                          prefixText: 'USD \$ ',
                          prefixStyle: TextStyle(color: kGold, fontSize: 16, fontWeight: FontWeight.w700),
                          border: InputBorder.none),
                        onChanged: (_) => _recalcular())),
                    ]),
                    Padding(padding: const EdgeInsets.symmetric(vertical: 10),
                      child: Container(height: 1, color: Colors.white.withOpacity(0.08))),
                    Row(children: [
                      Text(t('Equivale a','Equals'),
                        style: const TextStyle(color: kTextMuted, fontSize: 12)),
                    ]),
                    const SizedBox(height: 4),
                    Text(
                      _tasaUsdCop != null ? _formatoCop(_copResultado) : '—',
                      style: const TextStyle(color: kGreen, fontSize: 26, fontWeight: FontWeight.w900)),
                    const SizedBox(height: 10),
                    if (_tasaUsdCop != null)
                      Row(children: [
                        Text('1 USD ≈ ${_formatoCop(_tasaUsdCop!)} COP',
                          style: TextStyle(color: kTextMuted.withOpacity(0.7), fontSize: 11)),
                        const Spacer(),
                        if (_esOffline)
                          Container(
                            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                            decoration: BoxDecoration(
                              color: Colors.orange.withOpacity(0.15),
                              borderRadius: BorderRadius.circular(6)),
                            child: Text(t('Sin conexión · último valor','Offline · last value'),
                              style: const TextStyle(color: Colors.orange, fontSize: 9, fontWeight: FontWeight.w700))),
                      ])
                    else
                      Text(t('No se pudo obtener la tasa. Revisa tu conexión.',
                          'Could not fetch the rate. Check your connection.'),
                        style: const TextStyle(color: Colors.orange, fontSize: 11)),
                  ])),

            const SizedBox(height: 28),

            Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
              Text(t('Diccionario paisa','Paisa dictionary'),
                style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w900,
                  color: kTextMuted, letterSpacing: 1.5)),
              Text('${_palabrasAprendidas.length}/${kDiccionarioPaisa.length} ${t("aprendidas","learned")}',
                style: const TextStyle(color: kGold, fontSize: 11, fontWeight: FontWeight.w700)),
            ]),
            const SizedBox(height: 4),
            Text(t('Toca una palabra para marcarla como aprendida','Tap a word to mark it as learned'),
              style: TextStyle(color: kTextMuted.withOpacity(0.6), fontSize: 11)),
            const SizedBox(height: 16),

            // ── Palabra del día ──
            Builder(builder: (_) {
              final hoy = DateTime.now();
              final idx = (hoy.year * 365 + hoy.month * 30 + hoy.day) % kDiccionarioPaisa.length;
              final p = kDiccionarioPaisa[idx];
              return Container(
                padding: const EdgeInsets.all(16),
                margin: const EdgeInsets.only(bottom: 16),
                decoration: BoxDecoration(
                  gradient: LinearGradient(colors: [kGold.withOpacity(0.15), kGold.withOpacity(0.05)]),
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: kGold.withOpacity(0.4))),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    const Text('⭐', style: TextStyle(fontSize: 14)),
                    const SizedBox(width: 6),
                    Text(t('Palabra del día', 'Word of the day'),
                      style: const TextStyle(color: kGold, fontSize: 10, fontWeight: FontWeight.w900, letterSpacing: 1.5)),
                  ]),
                  const SizedBox(height: 8),
                  Text(p.palabra, style: const TextStyle(color: kGold, fontSize: 22, fontWeight: FontWeight.w900, letterSpacing: 1)),
                  const SizedBox(height: 4),
                  Text(t(p.significado, p.significadoEN), style: TextStyle(color: kTextMuted.withOpacity(0.9), fontSize: 13, height: 1.4)),
                  const SizedBox(height: 6),
                  Text(t(p.ejemplo, p.ejemploEN), style: TextStyle(color: kTextMuted.withOpacity(0.6), fontSize: 11, fontStyle: FontStyle.italic)),
                ]));
            }),

            const SizedBox(height: 4),
            ...kDiccionarioPaisa.map((p) {
              final aprendida = _palabrasAprendidas.contains(p.palabra);
              return GestureDetector(
                onTap: () => _marcarAprendida(p.palabra),
                child: Container(
                  margin: const EdgeInsets.only(bottom: 10),
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: kCard, borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                      color: aprendida ? kGold.withOpacity(0.4) : Colors.white.withOpacity(0.08))),
                  child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Container(width: 30, height: 30,
                      decoration: BoxDecoration(shape: BoxShape.circle,
                        color: aprendida ? kGold.withOpacity(0.15) : kDark3),
                      child: Center(child: Text(aprendida ? '✅' : '🗣️',
                        style: const TextStyle(fontSize: 14)))),
                    const SizedBox(width: 12),
                    Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text(p.palabra,
                        style: TextStyle(color: aprendida ? kGold : kText,
                          fontSize: 14, fontWeight: FontWeight.w800, letterSpacing: 0.5)),
                      const SizedBox(height: 4),
                      Text(t(p.significado, p.significadoEN),
                        style: TextStyle(color: kTextMuted.withOpacity(0.9), fontSize: 12, height: 1.4)),
                      const SizedBox(height: 6),
                      Text(t(p.ejemplo, p.ejemploEN),
                        style: TextStyle(color: kTextMuted.withOpacity(0.6), fontSize: 11,
                          fontStyle: FontStyle.italic, height: 1.4)),
                    ])),
                  ])));
            }),
          ])),
      ]));
  }

  @override
  void dispose() {
    _usdCtrl.dispose();
    super.dispose();
  }
}

// ═══════════════════════════════════════════════════════════════════════════
//  🆘 BOTÓN SOS
//  Configuración de contacto de emergencia (shared_preferences) +
//  obtención de GPS (mismo patrón de MapScreen) + envío por WhatsApp.
//  Sin backend nuevo, sin costo adicional.
// ═══════════════════════════════════════════════════════════════════════════

class SOSConfigScreen extends StatefulWidget {
  const SOSConfigScreen({super.key});
  @override
  State<SOSConfigScreen> createState() => _SOSConfigScreenState();
}

class _SOSConfigScreenState extends State<SOSConfigScreen> {
  final _nombreCtrl = TextEditingController();
  final _numeroCtrl = TextEditingController();
  bool _cargando = true;
  bool _guardando = false;
  bool _enviandoSOS = false;

  @override
  void initState() {
    super.initState();
    _cargarContacto();
  }

  Future<void> _cargarContacto() async {
    final prefs = await SharedPreferences.getInstance();
    _nombreCtrl.text = prefs.getString('sos_contacto_nombre') ?? '';
    _numeroCtrl.text = prefs.getString('sos_contacto_numero') ?? '';
    if (mounted) setState(() => _cargando = false);
  }

  Future<void> _guardarContacto() async {
    if (_nombreCtrl.text.trim().isEmpty || _numeroCtrl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('Completa nombre y número','Fill in name and number')),
        backgroundColor: Colors.orange));
      return;
    }
    setState(() => _guardando = true);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('sos_contacto_nombre', _nombreCtrl.text.trim());
    await prefs.setString('sos_contacto_numero', _numeroCtrl.text.trim());
    if (mounted) {
      setState(() => _guardando = false);
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('✅ Contacto de emergencia guardado','✅ Emergency contact saved')),
        backgroundColor: kGreen));
    }
  }

  Future<void> _enviarSOS() async {
    final numero = _numeroCtrl.text.trim();
    if (numero.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('Configura un contacto primero','Set up a contact first')),
        backgroundColor: Colors.orange));
      return;
    }
    setState(() => _enviandoSOS = true);
    try {
      LocationPermission p = await Geolocator.checkPermission();
      if (p == LocationPermission.denied) p = await Geolocator.requestPermission();
      if (p == LocationPermission.deniedForever || p == LocationPermission.denied) {
        if (mounted) {
          setState(() => _enviandoSOS = false);
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text(t('Activa el permiso de ubicación para enviar SOS',
                'Enable location permission to send SOS')),
            backgroundColor: Colors.orange));
        }
        return;
      }
      Position pos;
      try {
        pos = await Geolocator.getCurrentPosition(
          desiredAccuracy: LocationAccuracy.high,
        ).timeout(const Duration(seconds: 8));
      } catch (_) {
        // Fallback: precisión media, más rápida si el GPS de alta precisión tarda
        pos = await Geolocator.getCurrentPosition(
          desiredAccuracy: LocationAccuracy.medium,
        ).timeout(const Duration(seconds: 6));
      }
      final mapsLink = 'https://maps.google.com/?q=${pos.latitude},${pos.longitude}';
      final mensaje = Uri.encodeComponent(
        t('🆘 Necesito ayuda. Esta es mi ubicación actual: $mapsLink — Enviado desde Rutero MDE.',
          '🆘 I need help. This is my current location: $mapsLink — Sent from Rutero MDE.'));
      final numeroLimpio = numero.replaceAll(RegExp(r'[^\d+]'), '');
      final whatsappUri = Uri.parse('https://wa.me/$numeroLimpio?text=$mensaje');
      final abierto = await launchUrl(whatsappUri, mode: LaunchMode.externalApplication);
      if (!abierto && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('No se pudo abrir WhatsApp. ¿Está instalado?','Could not open WhatsApp. Is it installed?')),
          backgroundColor: Colors.red));
      }
    } catch (e) {
      debugPrint('🔴 Error enviando SOS: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('No se pudo obtener tu ubicación a tiempo. Verifica que el GPS esté activado e intenta de nuevo.',
              'Could not get your location in time. Make sure GPS is enabled and try again.')),
          backgroundColor: Colors.red,
          duration: const Duration(seconds: 4)));
      }
    } finally {
      if (mounted) setState(() => _enviandoSOS = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kDark2,
      body: Column(children: [
        Container(
          decoration: BoxDecoration(
            color: kDark2,
            border: Border(bottom: BorderSide(color: kGold.withOpacity(0.1)))),
          child: SafeArea(bottom: false, child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 20, 18),
            child: Row(children: [
              GestureDetector(onTap: () => Navigator.pop(context),
                child: Container(width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.06),
                    shape: BoxShape.circle,
                    border: Border.all(color: kGold.withOpacity(0.2))),
                  child: const Center(child: Text('←',
                    style: TextStyle(color: kText, fontSize: 16))))),
              const SizedBox(width: 12),
              Expanded(child: Text(t('Botón SOS','SOS Button'),
                style: const TextStyle(
                  fontFamily: 'PlayfairDisplay',
                  fontSize: 19, fontWeight: FontWeight.w900,
                  color: kText, letterSpacing: 0.3))),
              const Text('🆘', style: TextStyle(fontSize: 20)),
            ])))),
        Expanded(child: _cargando
