class _HomeBodyState extends State<HomeBody> {
  String _filtroActivo = 'Ciudad';
  String _busqueda = '';
  final TextEditingController _searchCtrl = TextEditingController();

  // ── Detección de ciudad por GPS (23/05/2026) ──
  _CiudadRegistrada? _ciudadDetectada;
  bool _cargandoCiudad = true;

  @override
  void initState() {
    super.initState();
    _detectarCiudad();
    // Escuchar cuando RutasService termina de cargar de Firestore
    RutasService().addListener(_onRutasCargadas);
  }

  void _onRutasCargadas() {
    if (mounted) setState(() {}); // Refrescar UI con rutas de Firestore
  }

  Future<void> _detectarCiudad() async {
    final ciudad = await detectarCiudadActual();
    if (mounted) setState(() { _ciudadDetectada = ciudad; _cargandoCiudad = false; });
  }

  // Rutas filtradas por ciudad detectada + filtro de zona activo
  List<Map<String, dynamic>> get _rutas {
    final porCiudad = filtrarRutasPorCiudad(_ciudadDetectada);
    return porCiudad;
  }

  @override
  void dispose() {
    _searchCtrl.dispose();
    RutasService().removeListener(_onRutasCargadas);
    super.dispose();
  }
  void _onTabTap(int index) {
    tabNotifier.value = index;
  }

  String _saludoHora() {
    final h = DateTime.now().hour;
    if (h < 12) return t('BUENOS DÍAS', 'GOOD MORNING');
    if (h < 18) return t('BUENAS TARDES', 'GOOD AFTERNOON');
    return t('BUENAS NOCHES', 'GOOD EVENING');
  }

  bool _rutaActivaEvento(Map<String, dynamic> ruta) {
    final recurrente = ruta['eventoRecurrente'];
    if (recurrente == 'fines_semana') {
      final dia = DateTime.now().weekday;
      return dia == DateTime.friday || dia == DateTime.saturday || dia == DateTime.sunday;
    }
    return _rutaActiva(ruta);
  }

  bool _rutaActiva(Map<String, dynamic> ruta) {
    // 🧪 Modo demo — admin ve todas las rutas de temporada activas
    if (kModoDemo) return true;
    final ahora = DateTime.now();
    final List? inicio = ruta['temporadaInicio'] as List?;
    final List? fin = ruta['temporadaFin'] as List?;

    // Si tiene rango exacto → usar rango (+7 días antes para promocionar)
    if (inicio != null && fin != null && inicio.length == 2 && fin.length == 2) {
      final int mI = inicio[0] as int, dI = inicio[1] as int;
      final int mF = fin[0] as int, dF = fin[1] as int;
      DateTime dtInicio = DateTime(ahora.year, mI, dI);
      DateTime dtFin = DateTime(ahora.year, mF, dF, 23, 59);
      // Rango que cruza año (ej: 1 dic → 15 ene)
      if (mF < mI) {
        // Si estamos antes del fin del próximo año, ajusta
        if (ahora.month <= mF) {
          dtInicio = DateTime(ahora.year - 1, mI, dI);
        } else {
          dtFin = DateTime(ahora.year + 1, mF, dF, 23, 59);
        }
      }
      // 7 días antes se puede ver (preview)
      final dtPreview = dtInicio.subtract(const Duration(days: 7));
      return ahora.isAfter(dtPreview) && ahora.isBefore(dtFin);
    }

    // Fallback al sistema viejo por meses
    final List<int> meses = List<int>.from(ruta['temporadaMeses'] ?? []);
    if (meses.isEmpty) return true;
    return meses.contains(ahora.month);
  }

  String _proximaActivacion(Map<String, dynamic> ruta) {
    final List? inicio = ruta['temporadaInicio'] as List?;
    if (inicio != null && inicio.length == 2) {
      final int m = inicio[0] as int, d = inicio[1] as int;
      return '$d de ${_mesNombre(m)}';
    }
    final List<int> meses = List<int>.from(ruta['temporadaMeses'] ?? []);
    if (meses.isEmpty) return '';
    return meses.map((m) => _mesNombre(m)).join(' · ');
  }

  int _diasParaActivacion(Map<String, dynamic> ruta) {
    final ahora = DateTime.now();
    final List? inicio = ruta['temporadaInicio'] as List?;

    if (inicio != null && inicio.length == 2) {
      final int m = inicio[0] as int, d = inicio[1] as int;
      DateTime prox = DateTime(ahora.year, m, d);
      if (prox.isBefore(ahora)) prox = DateTime(ahora.year + 1, m, d);
      return prox.difference(ahora).inDays;
    }

    final List<int> meses = List<int>.from(ruta['temporadaMeses'] ?? []);
    if (meses.isEmpty) return 0;
    int min = 999;
    for (final m in meses) {
      DateTime prox = DateTime(ahora.year, m, 1);
      if (prox.isBefore(ahora)) prox = DateTime(ahora.year + 1, m, 1);
      final d = prox.difference(ahora).inDays;
      if (d < min) min = d;
    }
    return min;
  }

  List<Map<String, dynamic>> get _rutasFiltradas {
    // Si hay búsqueda activa → buscar en TODAS las rutas (sin filtro de ciudad)
    final base = _busqueda.isNotEmpty ? RutasService().rutas : _rutas;
    return base.where((r) {
      if (_busqueda.isNotEmpty) {
        final q = _busqueda.toLowerCase();
        final nombre = r['nombre'].toString().toLowerCase();
        final sub = r['subtitulo'].toString().toLowerCase();
        final sitios = ((r['sitiosList'] as List?)?.map((s) => s.toString()).toList() ?? []).join(' ').toLowerCase();
        final ciudad = r['ciudad'].toString().toLowerCase();
        if (!nombre.contains(q) && !sub.contains(q) &&
            !sitios.contains(q) && !ciudad.contains(q)) return false;
      }
      if (_filtroActivo == 'Ciudad' && r['zona'] != 'Ciudad') return false;
      if (_filtroActivo == 'Alrededores' && r['zona'] != 'Alrededores') return false;
      if (_filtroActivo == 'Temporada' && r['zona'] != 'Temporada') return false;
      if (_filtroActivo == 'Comida Urbana' && r['zona'] != 'Comida Urbana') return false;
      if (_filtroActivo == 'Eventos' && r['zona'] != 'Eventos') return false;
      return true;
    }).toList();
  }

  int get _rutasActivas => _rutas.where((r) => _rutaActiva(r) || r['zona'] == 'Comida Urbana' || r['zona'] == 'Eventos').length;



