// ── Partícula de confetti ──
class _ConfettiParticle {
  final Color color;
  final double x, delay, size, speed;
  const _ConfettiParticle({
    required this.color, required this.x,
    required this.delay, required this.size, required this.speed});
}

// ── Painter de confetti ──
class _ConfettiPainter extends CustomPainter {
  final List<_ConfettiParticle> particles;
  final double progress;
  const _ConfettiPainter(this.particles, this.progress);

  @override
  void paint(Canvas canvas, Size size) {
    for (final p in particles) {
      final t = ((progress - p.delay) / (1 - p.delay)).clamp(0.0, 1.0);
      if (t <= 0) continue;
      final y = t * size.height * p.speed * 2.5;
      final x = p.x * size.width + (t * 40 * (p.x > 0.5 ? 1 : -1));
      final opacity = (1 - t * 0.8).clamp(0.0, 1.0);
      final paint = Paint()..color = p.color.withOpacity(opacity);
      canvas.save();
      canvas.translate(x, y);
      canvas.rotate(t * 6.28 * (p.x > 0.5 ? 1 : -1));
      canvas.drawRect(Rect.fromCenter(center: Offset.zero,
        width: p.size, height: p.size * 0.5), paint);
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(_ConfettiPainter old) => old.progress != progress;
}

