  void _mostrarEditarPerfil(BuildContext context) {
    final user = AuthService.currentUser;
    final nombreCtrl = TextEditingController(text: user?.displayName ?? '');
    bool _guardando = false;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: kCard,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setModal) => Padding(
          padding: EdgeInsets.only(
            left: 24, right: 24, top: 24,
            bottom: MediaQuery.of(context).viewInsets.bottom + 24),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [

            Text(t('Editar perfil','Edit profile'),
              style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w800, color: kText)),
            const SizedBox(height: 16),

            // Foto de perfil
            Center(child: GestureDetector(
              onTap: () async {
                final picker = ImagePicker();
                final XFile? img = await picker.pickImage(
                  source: ImageSource.gallery,
                  imageQuality: 80, maxWidth: 400);
                if (img == null) return;
                setModal(() => _guardando = true);
                try {
                  final ref = FirebaseStorage.instance
                    .ref('fotos_perfil/${user!.uid}.jpg');
                  await ref.putFile(File(img.path));
                  final url = await ref.getDownloadURL();
                  await user.updatePhotoURL(url);
                  if (ctx.mounted) setModal(() => _guardando = false);
                } catch (e) {
                  if (ctx.mounted) setModal(() => _guardando = false);
                  debugPrint('Error foto perfil: $e');
                }
              },
              child: Stack(alignment: Alignment.bottomRight, children: [
                Container(width: 80, height: 80,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    border: Border.all(color: kGold.withOpacity(0.5), width: 2),
                    boxShadow: [BoxShadow(color: kGold.withOpacity(0.2), blurRadius: 12)]),
                  child: ClipOval(child: user?.photoURL != null
                    ? Image.network(user!.photoURL!, fit: BoxFit.cover,
                        errorBuilder: (_, __, ___) => const Center(
                          child: Text('👤', style: TextStyle(fontSize: 32))))
                    : const Center(child: Text('👤', style: TextStyle(fontSize: 32))))),
                Container(width: 26, height: 26,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: kGreen,
                    border: Border.all(color: kCard, width: 2)),
                  child: const Center(child: Text('📷', style: TextStyle(fontSize: 12)))),
              ]))),

            const SizedBox(height: 16),

            // Campo nombre
            Container(
              decoration: BoxDecoration(color: kDark3, borderRadius: BorderRadius.circular(12),
                border: Border.all(color: Colors.white.withOpacity(0.1))),
              child: TextField(
                controller: nombreCtrl,
                style: const TextStyle(color: kText, fontSize: 14),
                decoration: InputDecoration(
                  hintText: t('Tu nombre','Your name'),
                  hintStyle: const TextStyle(color: kTextMuted),
                  prefixIcon: const Padding(padding: EdgeInsets.all(12),
                    child: Text('👤', style: TextStyle(fontSize: 16))),
                  border: InputBorder.none,
                  contentPadding: const EdgeInsets.symmetric(vertical: 14)))),

            const SizedBox(height: 8),

            // Email (no editable)
            Container(padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(color: kDark3, borderRadius: BorderRadius.circular(12),
                border: Border.all(color: Colors.white.withOpacity(0.06))),
              child: Row(children: [
                const Text('📧', style: TextStyle(fontSize: 16)),
                const SizedBox(width: 10),
                Text(user?.email ?? '', style: const TextStyle(color: kTextMuted, fontSize: 13)),
                const Spacer(),
                Text(tNoEditable, style: const TextStyle(color: kTextMuted, fontSize: 10)),
              ])),

            const SizedBox(height: 20),

            _GoldButton(
              label: _guardando
                ? t('GUARDANDO...','SAVING...')
                : t('GUARDAR CAMBIOS','SAVE CHANGES'),
              onTap: _guardando ? () {} : () async {
                setModal(() => _guardando = true);
                try {
                  if (nombreCtrl.text.trim().isNotEmpty) {
                    await user?.updateDisplayName(nombreCtrl.text.trim());
                  }
                } catch (e) {
                  debugPrint('Error guardando nombre: $e');
                }
                if (ctx.mounted) {
                  Navigator.pop(ctx);
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(content: Text(t('✅ Perfil actualizado','✅ Profile updated')),
                      backgroundColor: kGreen,
                      duration: const Duration(seconds: 2)));
                }
              }),
          ])))); 
  }

