          ]))),
        ]),  // cierre Stack banner+header

        Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          // Stats dinámicos desde subcolección 'progreso' (fuente confiable)
          StreamBuilder<QuerySnapshot>(
            stream: AuthService.currentUser != null
              ? FirebaseFirestore.instance.collection('usuarios')
                  .doc(AuthService.currentUser!.uid)
                  .collection('progreso')
                  .snapshots()
              : const Stream.empty(),
            builder: (ctx, snap) {
              final docs = snap.data?.docs ?? [];
              final rutasCompletadas = docs.where((d) => (d.data() as Map)['completada'] == true).length;
              int sitiosTotales = 0;
              int puntosTotales = 0;
              for (final d in docs) {
                final data = d.data() as Map<String, dynamic>;
                final completados = (data['sitiosCompletados'] as int? ?? 0);
                sitiosTotales += completados;
                puntosTotales += completados * 30;
                if (data['completada'] == true) puntosTotales += 50;
              }
              return Row(children: [
                _ProfileStat(valor: '$rutasCompletadas', label: t('Rutas\nCompletadas','Routes\nCompleted'), emoji: '🗺️'),
                const SizedBox(width: 10),
                _ProfileStat(valor: '$sitiosTotales', label: t('Sitios\nVisitados','Spots\nVisited'), emoji: '📍'),
                const SizedBox(width: 10),
                _ProfileStat(valor: '$puntosTotales', label: t('Puntos\nAcumulados','Points\nEarned'), emoji: '⭐'),
              ]);
            }),

          const SizedBox(height: 24),

          // Nivel dinámico
          Text(tProgresoNivel,
            style: TextStyle(fontSize: 12, fontWeight: FontWeight.w900, color: kTextMuted, letterSpacing: 2)),
          const SizedBox(height: 12),
          StreamBuilder<DocumentSnapshot>(
            stream: AuthService.currentUser != null
              ? FirebaseFirestore.instance.collection('usuarios').doc(AuthService.currentUser!.uid).snapshots()
              : const Stream.empty(),
            builder: (ctx, snap) {
              final data = snap.data?.data() as Map<String, dynamic>? ?? {};
              final puntos = (data['puntosTotal'] ?? 0) as int;
              // Niveles: 0→Novato, 300→Explorador, 700→Rutero, 1200→Aventurero, 2000→Leyenda
              final niveles = [
                {'min': 0,    'max': 299,  'nombre': t('Novato Rutero','Rutero Novice'),       'emoji': '🌱', 'siguiente': t('Explorador Urbano','Urban Explorer')},
                {'min': 300,  'max': 699,  'nombre': t('Explorador Urbano','Urban Explorer'),   'emoji': '🌿', 'siguiente': t('Rutero Paisa','Paisa Rutero')},
                {'min': 700,  'max': 1199, 'nombre': t('Rutero Paisa','Paisa Rutero'),        'emoji': '⛰️', 'siguiente': t('Aventurero','Adventurer')},
                {'min': 1200, 'max': 1999, 'nombre': t('Aventurero MDE','MDE Adventurer'),      'emoji': '🦅', 'siguiente': t('Leyenda','Legend')},
                {'min': 2000, 'max': 99999,'nombre': t('Leyenda de Medellín','Medellín Legend'), 'emoji': '🏆', 'siguiente': ''},
              ];
              final nivel = niveles.lastWhere((n) => puntos >= (n['min'] as int), orElse: () => niveles[0]);
              final maxNivel = nivel['max'] as int;
              final minNivel = nivel['min'] as int;
              final progreso = maxNivel < 99999
                ? (puntos - minNivel) / (maxNivel - minNivel + 1)
                : 1.0;
              final ptsFaltantes = maxNivel < 99999 ? maxNivel + 1 - puntos : 0;
              return Container(padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: kGold.withOpacity(0.15))),
                child: Column(children: [
                  Row(children: [
                    Container(width: 36, height: 36,
                      decoration: BoxDecoration(shape: BoxShape.circle,
                        gradient: LinearGradient(colors: [kGreen.withOpacity(0.3), kGold.withOpacity(0.2)])),
                      child: Center(child: Text(nivel['emoji'] as String, style: const TextStyle(fontSize: 18)))),
                    const SizedBox(width: 12),
                    Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text('${nivel['nombre']}', style: const TextStyle(color: kText, fontSize: 13, fontWeight: FontWeight.w600)),
                      Text('$puntos / ${maxNivel < 99999 ? maxNivel + 1 : puntos} ${t("puntos","pts")}',
                        style: const TextStyle(color: kTextMuted, fontSize: 11)),
                    ])),
                    Container(padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(color: kGold.withOpacity(0.1), borderRadius: BorderRadius.circular(8)),
                      child: Text('${(progreso * 100).toInt()}%',
                        style: const TextStyle(color: kGold, fontSize: 12, fontWeight: FontWeight.w700))),
                  ]),
                  const SizedBox(height: 12),
                  ClipRRect(borderRadius: BorderRadius.circular(6),
                    child: TweenAnimationBuilder<double>(
                      tween: Tween(begin: 0.0, end: progreso.clamp(0.0, 1.0)),
                      duration: const Duration(milliseconds: 900),
                      curve: Curves.easeOutCubic,
                      builder: (_, value, __) => LinearProgressIndicator(
                        value: value,
                        backgroundColor: Colors.white.withOpacity(0.06),
                        valueColor: const AlwaysStoppedAnimation<Color>(kGold),
                        minHeight: 10))),
                  const SizedBox(height: 8),
                  Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                    Text(maxNivel < 99999
                      ? '$ptsFaltantes ${t("pts para","pts to")} ${nivel['siguiente']} 🎯'
                      : t('¡Leyenda de Medellín! 🏆','Medellín Legend! 🏆'),
                      style: TextStyle(color: kTextMuted.withOpacity(0.7), fontSize: 10)),
                    if (maxNivel < 99999)
                      Text('${t("Próximo","Next")}: ${nivel['siguiente']}',
                        style: TextStyle(color: kGold.withOpacity(0.5), fontSize: 10)),
                  ]),
                ]));
            }),

          const SizedBox(height: 24),

          // Insignias
          Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
            Text(tInsigniasRecientes,
              style: TextStyle(fontSize: 12, fontWeight: FontWeight.w900, color: kTextMuted, letterSpacing: 2)),
            GestureDetector(
              onTap: () => Navigator.of(context, rootNavigator: false).push(MaterialPageRoute(builder: (_) => const AchievementsScreen())),
              child: Text(tVerTodas, style: const TextStyle(color: kGold, fontSize: 11))),
          ]),
          const SizedBox(height: 12),
          Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: const [
            _BadgeChip(emoji: '🌿', nombre: 'Explorador 13',
              insigniaImg: 'assets/images/insignias/insignia_01_explorador_13.png',
              desbloqueado: true),
            _BadgeChip(emoji: '🏛️', nombre: 'Guardián',
              insigniaImg: 'assets/images/insignias/insignia_02_guardian_patrimonio.png',
              desbloqueado: true),
            _BadgeChip(emoji: '🌿', nombre: 'Guardabosque',
              insigniaImg: 'assets/images/insignias/insignia_03_guardabosque.png',
              desbloqueado: true),
            _BadgeChip(emoji: '🌸', nombre: 'Cóndor',
              insigniaImg: 'assets/images/insignias/insignia_07_condor_andes.png',
              desbloqueado: false),
          ]),

          const SizedBox(height: 24),

          // Menú
          Text(tConfiguracion,
            style: TextStyle(fontSize: 12, fontWeight: FontWeight.w900, color: kTextMuted, letterSpacing: 2)),
          const SizedBox(height: 12),
          GestureDetector(
            onTap: () => Navigator.of(context, rootNavigator: false).push(MaterialPageRoute(builder: (_) => const MisPremiosScreen())),
            child: Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(14),
                border: Border.all(color: kGold.withOpacity(0.3))),
              child: Row(children: [
                const Text('🏆', style: TextStyle(fontSize: 22)),
                const SizedBox(width: 14),
                Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(tMisPremiosPerfil, style: const TextStyle(color: kGold, fontSize: 14, fontWeight: FontWeight.w600)),
                  Text(tCodigosQR, style: const TextStyle(color: kTextMuted, fontSize: 11)),
                ])),
                const Icon(Icons.chevron_right, color: kTextMuted, size: 18),
              ]))),
          _ProfileMenuItem(
            emoji: '📸', label: t('Mis fotos','My photos'),
            onTap: () => Navigator.of(context, rootNavigator: false).push(
              MaterialPageRoute(builder: (_) => const MisFotosScreen()))),
          _ProfileMenuItem(
            emoji: '✏️', label: t('Editar perfil','Edit profile'),
            onTap: () => _mostrarEditarPerfil(context)),
          _ProfileMenuItem(
            emoji: '🔔', label: t('Notificaciones','Notifications'),
            onTap: () => _mostrarNotificaciones(context)),

          _ProfileMenuItem(
            emoji: '🎵', label: t('Configuración de audio','Audio settings'),
            onTap: () => _mostrarAudio(context)),
          _ProfileMenuItem(
            emoji: '👁️', label: t('Previsualizar perfil público', 'Preview public profile'),
            onTap: () {
              final user = AuthService.currentUser;
              final nombre = user?.displayName ?? user?.email?.split('@').first ?? 'Rutero';
              Navigator.of(context).push(MaterialPageRoute(
                builder: (_) => PerfilPublicoScreen(usuario: nombre)));
            }),
          _ProfileMenuItem(
            emoji: '📤', label: t('Compartir mi perfil', 'Share my profile'),
            onTap: () {
              final user = AuthService.currentUser;
              final nombre = user?.displayName ?? user?.email?.split('@').first ?? 'Rutero';
              final link = DeepLinkManager.linkPerfil(nombre);
              final texto = t(
                '¡Mira mis insignias en Rutero MDE! 🌿\n$link\n#RuteroMDE #Medellín',
                'Check out my badges on Rutero MDE! 🌿\n$link\n#RuteroMDE #Medellin');
              Share.share(texto);
            }),



          _ProfileMenuItem(
            emoji: '🎬', label: t('Colaboradores','Collaborators'),
            onTap: () => Navigator.of(context, rootNavigator: false).push(
              MaterialPageRoute(builder: (_) => const ColaboradoresScreen()))),
          _ProfileMenuItem(
            emoji: '❓', label: t('Ayuda y soporte','Help & support'),
            onTap: () => _mostrarAyuda(context)),
          // 💰 Toggle moneda — solo visible para admin/desarrollador
          if (esAdmin) _ProfileMenuItem(
            emoji: '💰',
            label: esTurista
              ? t('Moneda: USD → Cambiar a COP', 'Currency: USD → Switch to COP')
              : t('Moneda: COP → Cambiar a USD', 'Currency: COP → Switch to USD'),
            onTap: () {
              if (monedaOverride.value == null) {
                monedaOverride.value = esTurista ? 'COP' : 'USD';
              } else if (monedaOverride.value == 'COP') {
                monedaOverride.value = 'USD';
              } else {
                monedaOverride.value = 'COP';
              }
              langNotifier.value = langNotifier.value;
            }),
          ValueListenableBuilder<String>(
            valueListenable: langNotifier,
            builder: (_, lang, __) => _ProfileMenuItem(
              emoji: '🌐',
              label: lang == 'es' ? '🇨🇴 Español  →  English 🇺🇸' : '🇺🇸 English  →  Español 🇨🇴',
              onTap: () => setLang(lang == 'es' ? 'en' : 'es'))),
          // ── Toggle MODO DEMO — solo visible para el admin ──
          // Permite alternar entre GPS real (campo) y simulado (oficina)
          // sin recompilar la app. Los usuarios normales nunca ven esta opción.
          if (esAdmin) ValueListenableBuilder<bool>(
            valueListenable: kModoDemoNotifier,
            builder: (_, demoActivo, __) => _ProfileMenuItem(
              emoji: demoActivo ? '🧪' : '🛰️',
              label: demoActivo
                ? t('Modo DEMO (GPS simulado) — ACTIVO', 'DEMO mode (simulated GPS) — ON')
                : t('Modo PRODUCCIÓN (GPS real)', 'PRODUCTION mode (real GPS)'),
              onTap: () async {
                await toggleModoDemo();
                if (context.mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                    content: Text(kModoDemo
                      ? t('🧪 Modo DEMO activado — el GPS aparecerá siempre dentro del rango',
                          '🧪 DEMO mode ON — GPS will always appear in range')
                      : t('🛰️ Modo PRODUCCIÓN activado — GPS real, validación por ubicación',
                          '🛰️ PRODUCTION mode ON — real GPS, location-based validation')),
                    backgroundColor: kModoDemo ? kOrchid : kGreen,
                    duration: const Duration(seconds: 3),
                  ));
                }
              })),
          _ProfileMenuItem(
            emoji: '💬',
            label: t('Dar mi opinión · Beta', 'Share feedback · Beta'),
            onTap: () => Navigator.of(context, rootNavigator: false).push(
              MaterialPageRoute(builder: (_) => const FeedbackBetaScreen()))),
          const SizedBox(height: 4),
          _ProfileMenuItem(
            emoji: '🚪', label: tCerrarSesion, isRed: true,
            onTap: () async {
              await AuthService.signOut();
              if (context.mounted) {
                Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
                  PageRouteBuilder(
                    pageBuilder: (_, __, ___) => const SplashScreen(),
                    transitionsBuilder: (_, anim, __, child) =>
                      FadeTransition(opacity: anim, child: child),
                    transitionDuration: const Duration(milliseconds: 500)),
                  (route) => false);
              }
            }),
          const SizedBox(height: 80),
        ])),
      ])),
    );
  }
}

// ─────────────────────────────────────────
//  LOGROS E INSIGNIAS
// ─────────────────────────────────────────
class AchievementsScreen extends StatelessWidget {
  const AchievementsScreen({super.key});

  static String _nombreInsignia(String rutaNombre) {
    try {
      final ruta = RutasService().rutas.firstWhere(
        (r) => r['nombre'] == rutaNombre, orElse: () => {});
      return ruta['insignia']?.toString() ?? rutaNombre;
    } catch (_) { return rutaNombre; }
  }

  static String _emojiRuta(String rutaNombre) {
    try {
      final ruta = RutasService().rutas.firstWhere(
        (r) => r['nombre'] == rutaNombre, orElse: () => {});
      return ruta['emoji']?.toString() ?? '🏅';
    } catch (_) { return '🏅'; }
  }

  @override
  Widget build(BuildContext context) {
    final user = AuthService.currentUser;
    if (user == null) return const Scaffold(backgroundColor: kDark2,
      body: Center(child: Text('Inicia sesión para ver tus logros',
        style: TextStyle(color: kTextMuted))));

    final todasInsignias = kInsigniaPorRuta.entries.map((e) => {
      'rutaNombre': e.key,
      'insigniaImg': e.value,
      'nombre': _nombreInsignia(e.key),
      'emoji': _emojiRuta(e.key),
    }).toList();

    return Scaffold(
      backgroundColor: kDark2,
      body: StreamBuilder<QuerySnapshot>(
        stream: FirebaseFirestore.instance
          .collection('usuarios').doc(user.uid)
          .collection('insignias').snapshots(),
        builder: (ctx, snap) {
          final insigniasGanadas = snap.hasData
            ? snap.data!.docs.map((d) => d.id).toSet()
            : <String>{};
          final puntosTotal = snap.hasData
            ? snap.data!.docs.fold<int>(0, (s, d) {
                final data = d.data() as Map<String, dynamic>;
                return s + ((data['puntos'] as int?) ?? 0);
              })
            : 0;

          final ganadas = todasInsignias.where((i) =>
            insigniasGanadas.contains(i['rutaNombre'])).toList();
          final bloqueadas = todasInsignias.where((i) =>
            !insigniasGanadas.contains(i['rutaNombre'])).toList();

          return Column(children: [
            // ── Header ──
            Container(
              decoration: BoxDecoration(
                color: kDark2,
                border: Border(bottom: BorderSide(color: kGold.withOpacity(0.1)))),
              child: SafeArea(bottom: false, child: Padding(
                padding: const EdgeInsets.fromLTRB(20, 12, 20, 20),
                child: Column(children: [
                  Row(children: [
                    if (Navigator.canPop(context))
                      GestureDetector(onTap: () => Navigator.pop(context),
                        child: Container(width: 36, height: 36,
                          decoration: BoxDecoration(
                            color: Colors.white.withOpacity(0.06),
                            shape: BoxShape.circle,
                            border: Border.all(color: kGold.withOpacity(0.2))),
                          child: const Center(child: Text('←',
                            style: TextStyle(color: kText, fontSize: 16))))),
                    if (Navigator.canPop(context)) const SizedBox(width: 12),
                    Expanded(child: Text(tMisLogrosTitle,
                      style: const TextStyle(
                        fontFamily: 'PlayfairDisplay',
                        fontSize: 20, fontWeight: FontWeight.w900,
                        color: kText, letterSpacing: 0.5))),
                    const Text('🏆', style: TextStyle(fontSize: 22)),
                  ]),
                  const SizedBox(height: 16),
                  Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [
                    _LogroStat(valor: '${ganadas.length}',
                      label: t('Desbloqueadas','Unlocked'), color: kGold),
                    _LogroStat(valor: '${todasInsignias.length}',
                      label: t('Total','Total'), color: kTextMuted),
                    _LogroStat(valor: '$puntosTotal',
                      label: t('Puntos','Points'), color: kGreen),
                  ]),
                  const SizedBox(height: 12),
                  ClipRRect(borderRadius: BorderRadius.circular(4),
                    child: LinearProgressIndicator(
                      value: todasInsignias.isEmpty ? 0
                        : ganadas.length / todasInsignias.length,
                      backgroundColor: Colors.white.withOpacity(0.06),
                      valueColor: const AlwaysStoppedAnimation<Color>(kGold),
                      minHeight: 4)),
                  const SizedBox(height: 6),
                  Text(
                    '${((ganadas.length / (todasInsignias.isEmpty ? 1 : todasInsignias.length)) * 100).toInt()}% ${t("de la colección","of the collection")}',
                    style: const TextStyle(
                      fontFamily: 'SpaceGrotesk',
                      fontSize: 10, color: kGold)),
                ])))),
            Expanded(child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(16, 20, 16, 80),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                if (ganadas.isNotEmpty) ...[
                  Text(tDesbloqueados,
                    style: const TextStyle(fontFamily: 'SpaceGrotesk',
                      fontSize: 11, color: kGold,
                      fontWeight: FontWeight.w700, letterSpacing: 2)),
                  const SizedBox(height: 12),
                  GridView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 3, crossAxisSpacing: 12,
                      mainAxisSpacing: 12, childAspectRatio: 0.8),
                    itemCount: ganadas.length,
                    itemBuilder: (_, idx) => _InsigniaCell(
                      insignia: ganadas[idx], desbloqueada: true,
                      onTap: () => _mostrarDetalle(context, ganadas[idx], true))),
                  const SizedBox(height: 28),
                ],
                Text(tPorDesbloquearTab,
                  style: const TextStyle(fontFamily: 'SpaceGrotesk',
                    fontSize: 11, color: kTextMuted,
                    fontWeight: FontWeight.w700, letterSpacing: 2)),
                const SizedBox(height: 12),
                GridView.builder(
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 3, crossAxisSpacing: 12,
                    mainAxisSpacing: 12, childAspectRatio: 0.8),
                  itemCount: bloqueadas.length,
                  itemBuilder: (_, idx) => _InsigniaCell(
                    insignia: bloqueadas[idx], desbloqueada: false,
                    onTap: () => _mostrarDetalle(context, bloqueadas[idx], false))),
              ]))),
          ]);
        }));
  }

  void _mostrarDetalle(BuildContext context, Map<String, dynamic> insignia, bool desbloqueada) {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      isScrollControlled: true,
      builder: (_) => _InsigniaDetalleSheet(
        insignia: insignia, desbloqueada: desbloqueada));
  }
}

class _InsigniaCell extends StatelessWidget {
  final Map<String, dynamic> insignia;
  final bool desbloqueada;
  final VoidCallback onTap;
  const _InsigniaCell({required this.insignia, required this.desbloqueada, required this.onTap});

  @override
  Widget build(BuildContext context) => GestureDetector(
    onTap: onTap,
    child: Container(
      decoration: BoxDecoration(
        color: kCard, borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: desbloqueada ? kGold.withOpacity(0.35) : Colors.white.withOpacity(0.06)),
        boxShadow: desbloqueada
          ? [BoxShadow(color: kGold.withOpacity(0.1), blurRadius: 12)] : null),
      child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
        Container(width: 64, height: 64,
          decoration: BoxDecoration(shape: BoxShape.circle,
            color: desbloqueada ? kGold.withOpacity(0.1) : kDark3,
            border: Border.all(
              color: desbloqueada ? kGold.withOpacity(0.4) : Colors.white.withOpacity(0.08))),
          child: desbloqueada
            ? ClipOval(child: Image.asset(insignia['insigniaImg'] ?? '',
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) => Center(
                  child: Text(insignia['emoji'] ?? '🏅',
                    style: const TextStyle(fontSize: 28)))))
            : const Center(child: Text('🔒',
                style: TextStyle(fontSize: 26, color: kTextMuted)))),
        const SizedBox(height: 8),
        Padding(padding: const EdgeInsets.symmetric(horizontal: 6),
          child: Text(insignia['nombre'] ?? '',
            style: TextStyle(fontFamily: 'Inter', fontSize: 9,
              color: desbloqueada ? kText : kTextMuted,
              fontWeight: desbloqueada ? FontWeight.w700 : FontWeight.w400,
              height: 1.3),
            textAlign: TextAlign.center,
            maxLines: 2, overflow: TextOverflow.ellipsis)),
      ])));
}

class _InsigniaDetalleSheet extends StatelessWidget {
  final Map<String, dynamic> insignia;
  final bool desbloqueada;
  const _InsigniaDetalleSheet({required this.insignia, required this.desbloqueada});

  @override
  Widget build(BuildContext context) {
    Map<String, dynamic> ruta = {};
    try {
      ruta = RutasService().rutas.firstWhere(
        (r) => r['nombre'] == insignia['rutaNombre'], orElse: () => {});
    } catch (_) {}
    final acento = kRutaColor(ruta['acento'], kGold);

    return Container(
      decoration: const BoxDecoration(color: kCard,
        borderRadius: BorderRadius.vertical(top: Radius.circular(28))),
      padding: const EdgeInsets.fromLTRB(24, 12, 24, 36),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        Container(width: 40, height: 4,
          decoration: BoxDecoration(color: Colors.white.withOpacity(0.15),
            borderRadius: BorderRadius.circular(2))),
        const SizedBox(height: 24),
        Container(width: 110, height: 110,
          decoration: BoxDecoration(shape: BoxShape.circle,
            color: desbloqueada ? acento.withOpacity(0.12) : kDark3,
            border: Border.all(
              color: desbloqueada ? acento.withOpacity(0.5) : Colors.white.withOpacity(0.1),
              width: 2),
            boxShadow: desbloqueada
              ? [BoxShadow(color: acento.withOpacity(0.3), blurRadius: 30, spreadRadius: 4)] : null),
          child: desbloqueada
            ? ClipOval(child: Image.asset(insignia['insigniaImg'] ?? '',
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) => Center(
                  child: Text(insignia['emoji'] ?? '🏅',
                    style: const TextStyle(fontSize: 52)))))
            : const Center(child: Text('🔒',
                style: TextStyle(fontSize: 48, color: kTextMuted)))),
        const SizedBox(height: 20),
        Text(insignia['nombre'] ?? '',
          style: const TextStyle(fontFamily: 'PlayfairDisplay',
            fontSize: 22, fontWeight: FontWeight.w900, color: kText),
          textAlign: TextAlign.center),
        const SizedBox(height: 6),
        Text(insignia['rutaNombre'] ?? '',
          style: TextStyle(fontSize: 11, color: acento,
            fontFamily: 'SpaceGrotesk', letterSpacing: 0.5),
          textAlign: TextAlign.center),
        const SizedBox(height: 16),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
          decoration: BoxDecoration(
            color: desbloqueada ? kGold.withOpacity(0.1) : kDark3,
            borderRadius: BorderRadius.circular(20),
            border: Border.all(
              color: desbloqueada ? kGold.withOpacity(0.4) : Colors.white.withOpacity(0.08))),
          child: Text(
            desbloqueada
              ? t('✅ Insignia desbloqueada', '✅ Badge unlocked')
              : t('🔒 Completa la ruta para desbloquear', '🔒 Complete the route to unlock'),
            style: TextStyle(fontFamily: 'SpaceGrotesk', fontSize: 11,
              color: desbloqueada ? kGold : kTextMuted,
              fontWeight: FontWeight.w700))),
        if (ruta['descripcion'] != null) ...[
          const SizedBox(height: 16),
          Text(ruta['descripcion'].toString(),
            style: const TextStyle(color: kTextMuted, fontSize: 12, height: 1.5),
            textAlign: TextAlign.center,
            maxLines: 3, overflow: TextOverflow.ellipsis),
        ],
        const SizedBox(height: 20),
        if (!desbloqueada && ruta.isNotEmpty)
          _GoldButton(
            label: t('🗺️  IR A LA RUTA', '🗺️  GO TO ROUTE'),
            onTap: () {
              Navigator.pop(context);
              RuteroNav.push(context, RouteDetailScreen(ruta: ruta));
            }),
      ]));
  }
}


