  // Zona de cada ruta para elegir ícono
  String _zonaDeRuta(String ruta) {
    if (['RUTA TRANSFORMACIÓN URBANA','RUTA PATRIMONIAL DEL CENTRO','RUTA VERDE DEL NORTE',
         'RUTA DEL METROCABLE & ARVÍ','RUTA LAURELES & TRADICIÓN',
         'RUTA DE LOS MIRADORES','RUTA CULTURAL NOCTURNA',
         'SENDEROS DE AGUA Y NATURALEZA','ARTE, CIUDAD Y SABORES',
         'DEL ORIGEN PAISA A LA MEDELLÍN MODERNA','TRANVÍA CULTURAL'].contains(ruta)) return 'Ciudad';
    if (['RUTA GUATAPÉ & LA PIEDRA','RUTA DEL CAFÉ EN SANTA ELENA','RUTA SAN CARLOS & CHARCOS',
         'RUTA JARDÍN COLONIAL','RUTA SANTA FE DE ANTIOQUIA','RUTA ENVIGADO NATURAL',
                       'RUTA MONTAÑA Y ANCESTRALIDAD — TÁMESIS','RUTA JOYA COLONIAL OCULTA — CONCEPCIÓN',
         'RUTA CARIBE ANTIOQUEÑO — NECOCLÍ'].contains(ruta)) return 'Alrededores';
    return 'Temporada';
  }

  Set<Marker> _buildMarkers() {
    final bool selHay = _sitioSeleccionado != null;
    final Set<Marker> markers = {};

    for (final sitio in _sitiosFiltrados) {
      final bool bloqueado = _rutaBloqueada(sitio.ruta);
      final bool visible = _sitioVisible(sitio);

      // Si la ruta está bloqueada y NO es el primer sitio → no mostrar
      if (bloqueado && !visible) continue;

      // Deduplicar pines bloqueados con mismas coordenadas — agrupar si hay varios
      if (bloqueado) {
        final String coordKey = sitio.posicion.latitude.toStringAsFixed(4) + ',' + sitio.posicion.longitude.toStringAsFixed(4);
        final String lockId = 'lock_' + coordKey;
        if (markers.any((m) => m.markerId.value == lockId)) continue;
      }

      final bool esSel = selHay && sitio.nombre == (_sitioSeleccionado?.nombre ?? '');
      BitmapDescriptor icon;

      // Fallback: marcador neutro — evita el pin verde nativo de Google Maps
      // que aparecía debajo del logo Rutero cuando el icono custom tardaba en cargar.
      // BitmapDescriptor.defaultMarker es el pin rojo estándar y no genera conflicto visual.
      final BitmapDescriptor _logoFallback =
        _iconCache['Logo'] ?? BitmapDescriptor.defaultMarker;

      if (bloqueado) {
        final String coordKey = sitio.posicion.latitude.toStringAsFixed(4) + ',' + sitio.posicion.longitude.toStringAsFixed(4);
        final int rutasEnPunto = _sitiosFiltrados.where((s) {
          if (!_rutaBloqueada(s.ruta)) return false;
          final primero = kSitiosMapa.where((x) => x.ruta == s.ruta).isNotEmpty
              ? kSitiosMapa.where((x) => x.ruta == s.ruta).first
              : null;
          if (primero == null) return false;
          return primero.posicion.latitude.toStringAsFixed(4) + ',' + primero.posicion.longitude.toStringAsFixed(4) == coordKey;
        }).map((s) => s.ruta).toSet().length;

        if (rutasEnPunto > 1) {
          icon = _iconCache['Agrupado_${rutasEnPunto.clamp(2,4)}'] ?? _iconCache['PinBloqueado'] ?? _logoFallback;
        } else {
          icon = _iconCache['PinBloqueado'] ?? _logoFallback;
        }
      } else if (esSel) {
        icon = _iconCache['LogoSel'] ?? _logoFallback;
      } else if (sitio.visitado) {
        icon = _iconCache['LogoVisitado'] ?? _logoFallback;
      } else {
        icon = _iconCache['Logo'] ?? _logoFallback;
      }

      // markerId único — sin escapado erróneo
      final String mId = bloqueado
        ? 'lock_${sitio.posicion.latitude.toStringAsFixed(4)},${sitio.posicion.longitude.toStringAsFixed(4)}'
        : sitio.nombre;
      markers.add(Marker(
        markerId: MarkerId(mId),
        position: sitio.posicion,
        icon: icon,
        zIndex: esSel ? 2.0 : (bloqueado ? 0.5 : 1.0),
        anchor: const Offset(0.5, 1.0),
        onTap: () {
          if (bloqueado) {
            setState(() => _sitioSeleccionado = sitio);
            _mostrarAlertaBloqueado(sitio.ruta);
          } else {
            setState(() => _sitioSeleccionado = sitio);
            _mapController?.animateCamera(
              CameraUpdate.newLatLngZoom(sitio.posicion, 16));
          }
        },
      ));
    }
    return markers;
  }

  void _mostrarAlertaBloqueado(String ruta) {
    final sitio = kSitiosMapa.firstWhere(
      (s) => s.ruta == ruta,
      orElse: () => _SitioMapa(nombre:'', emoji:'🗺️', posicion: const LatLng(0,0), ruta: ruta, color: kGold));
    final String emoji = sitio.emoji.isNotEmpty ? sitio.emoji : '🗺️';
    showModalBottomSheet(
      context: context,
      backgroundColor: kCard,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (_) => Padding(
        padding: const EdgeInsets.all(24),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Container(width: 40, height: 4,
            decoration: BoxDecoration(color: Colors.white24, borderRadius: BorderRadius.circular(2))),
          const SizedBox(height: 20),
          Text(emoji, style: const TextStyle(fontSize: 36)),
          const SizedBox(height: 4),
          const Text('🔒', style: TextStyle(fontSize: 28)),
          const SizedBox(height: 12),
          Text(ruta, textAlign: TextAlign.center,
            style: const TextStyle(color: kText, fontSize: 15, fontWeight: FontWeight.w800)),
          const SizedBox(height: 8),
          Text(tRutaBloqueadaMsg,
            textAlign: TextAlign.center,
            style: const TextStyle(color: kTextMuted, fontSize: 13, height: 1.5)),
          const SizedBox(height: 20),
          GestureDetector(
            onTap: () {
              if (Navigator.canPop(context)) Navigator.pop(context);
              final rutaCompleta = RutasService().rutas.firstWhere(
                (r) => r['nombre'] == ruta,
                orElse: () => {
                  'nombre': ruta,
                  'precio': r'$19.900',
                  'emoji': emoji,
                  'acento': _colorParaRuta(ruta),
                  'color1': kDark2,
                  'color2': kDark3,
                  'imagen': _imagenParaRuta(ruta),
                });
              // 🚧 Ruta pausada → no abrir, mostrar mensaje
              if (rutaCompleta['pausada'] == true) {
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                  content: Text(t(
                    '🚧 Esta ruta estará disponible pronto',
                    '🚧 This route will be available soon')),
                  backgroundColor: kDark2,
                  duration: const Duration(seconds: 2)));
                return;
              }
              // 🚀 Modo lanzamiento → ir directo al detalle
              Navigator.of(context).push(MaterialPageRoute(
                builder: (_) => RouteDetailScreen(ruta: rutaCompleta)));
            },
            child: Builder(builder: (ctx) {
              final rutaData = RutasService().rutas.firstWhere(
                (r) => r['nombre'] == ruta, orElse: () => {'pausada': false});
              final esPausada = rutaData['pausada'] == true;
              return Container(width: double.infinity,
                padding: const EdgeInsets.symmetric(vertical: 14),
                decoration: BoxDecoration(
                  gradient: LinearGradient(colors: esPausada
                    ? [kDark2, kDark3]
                    : [kGreen, kGreen.withOpacity(0.7)]),
                  borderRadius: BorderRadius.circular(14),
                  border: esPausada
                    ? Border.all(color: kTextMuted.withOpacity(0.3))
                    : null),
                child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                  Text(esPausada ? '🚧' : '🗺️', style: const TextStyle(fontSize: 18)),
                  const SizedBox(width: 8),
                  Text(
                    esPausada
                      ? t('PRÓXIMAMENTE', 'COMING SOON')
                      : t('VER RUTA GRATIS →', 'VIEW FREE ROUTE →'),
                    style: TextStyle(
                      color: esPausada ? kTextMuted : Colors.white,
                      fontSize: 13, fontWeight: FontWeight.w800, letterSpacing: 1)),
                ]));
            }),
          ),
          const SizedBox(height: 8),
        ])));
  }

