  double _hueParaRuta(String ruta) {
    if (ruta.contains('Patrimonial') || ruta.contains('Nocturna')) return BitmapDescriptor.hueViolet;
    if (ruta.contains('Gourmet') || ruta.contains('Café') || ruta.contains('Laureles')) return BitmapDescriptor.hueOrange;
    if (ruta.contains('Guatapé') || ruta.contains('Metrocable') || ruta.contains('San Carlos')) return BitmapDescriptor.hueAzure;
    if (ruta.contains('Miradores') || ruta.contains('Santa Fe') || ruta.contains('Alumbrado')) return BitmapDescriptor.hueYellow;
    return BitmapDescriptor.hueGreen;
  }

  Color _colorParaRuta(String ruta) {
    // ── Rutas gastronómicas ──
    if (ruta.contains('SABOR DE BARRIO'))   return kCafeLight;
    if (ruta.contains('SABOR DE CANCHA'))   return kGreen;
    if (ruta.contains('SABOR VIAJERO'))     return kGold;
    if (ruta.contains('SABOR PAISA'))       return kAccent;
    if (ruta.contains('SABOR URBANO'))      return kOrchid;
    // ── Parque Jaime Duque — colores institucionales del parque ──
    if (ruta.contains('CLÁSICA'))           return const Color(0xFF2E7D32); // Verde institucional
    if (ruta.contains('FAMILIA') && ruta.contains('JAIME')) return const Color(0xFFF9A825); // Amarillo institucional
    if (ruta.contains('NATURALEZA'))        return const Color(0xFF1B5E20); // Verde bosque profundo
    if (ruta.contains('AVENTURA FAMILIAR')) return const Color(0xFF1565C0); // Azul agua/Caribe
    // ── Rutas Medellín ──
    if (ruta.contains('Patrimonial') || ruta.contains('Nocturna') || ruta.contains('Navideño')) return kOrchid;
    if (ruta.contains('Gourmet') || ruta.contains('Café') || ruta.contains('Laureles')) return kCafe;
    if (ruta.contains('Guatapé') || ruta.contains('Metrocable') || ruta.contains('Arví')) return const Color(0xFF4A90D9);
    if (ruta.contains('San Carlos')) return const Color(0xFF2AB8D0);
    if (ruta.contains('Miradores') || ruta.contains('Santa Fe')) return kGold;
    if (ruta.contains('Alumbrado')) return const Color(0xFFFFD700);
    return kGreen;
  }

  Set<Polyline> get _polylines {
    final Set<Polyline> lines = {};
    final Map<String, List<_SitioMapa>> porRuta = {};
    // Solo polylines de rutas desbloqueadas
    for (final s in _sitiosFiltrados) {
      if (_rutaBloqueada(s.ruta)) continue;
      porRuta.putIfAbsent(s.ruta, () => []).add(s);
    }
    porRuta.forEach((ruta, sitios) {
      if (sitios.length < 2) return;
      final Color c = _colorParaRuta(ruta);
      // Línea de fondo más gruesa (glow)
      lines.add(Polyline(polylineId: PolylineId('${ruta}_glow'),
        points: sitios.map((s) => s.posicion).toList(),
        color: c.withOpacity(0.25), width: 8,
        patterns: [PatternItem.dash(20), PatternItem.gap(8)]));
      // Línea principal
      lines.add(Polyline(polylineId: PolylineId(ruta),
        points: sitios.map((s) => s.posicion).toList(),
        color: c.withOpacity(0.9), width: 3,
        patterns: [PatternItem.dash(20), PatternItem.gap(8)]));
    });
    return lines;
  }

