          Image.asset(widget.ruta['insigniaImg'], width: 140, height: 140,
            errorBuilder: (_, __, ___) =>
              Text(widget.ruta['personaje'] ?? '🏆', style: const TextStyle(fontSize: 52)))
        else
          Text(widget.ruta['personaje'] ?? '🏆', style: const TextStyle(fontSize: 52)),
        const SizedBox(height: 8),
        Text(t('¡RUTA COMPLETADA!', 'ROUTE COMPLETED!'),
          style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900,
            color: acento, letterSpacing: 2)),
        const SizedBox(height: 6),
        // Insignia
        if (widget.ruta['insignia'] != null)
          Container(
            margin: const EdgeInsets.only(bottom: 10),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 5),
            decoration: BoxDecoration(
              color: acento.withOpacity(0.15),
              borderRadius: BorderRadius.circular(20),
              border: Border.all(color: acento.withOpacity(0.4))),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Text(widget.ruta['personaje'] ?? '🏅', style: const TextStyle(fontSize: 16)),
