  Widget build(BuildContext context) {
    final String nombre   = aliado['nombre']?.toString() ?? '';
    final String emoji    = aliado['emoji']?.toString() ?? '🤝';
    final String beneficio = aliado['beneficio']?.toString() ?? '';
    final String direccion = aliado['direccion']?.toString() ?? '';
    final String whatsapp  = aliado['whatsapp']?.toString() ?? aliado['contacto']?.toString() ?? '';

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: kCard,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: kGreen.withOpacity(0.35))),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Text(emoji, style: const TextStyle(fontSize: 22)),
          const SizedBox(width: 10),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(t('ALIADO DE ESTA RUTA', 'ROUTE PARTNER'),
              style: TextStyle(color: kGreen, fontSize: 9, fontWeight: FontWeight.w700, letterSpacing: 1.5)),
            const SizedBox(height: 2),
            Text(nombre, style: const TextStyle(color: kText, fontSize: 13, fontWeight: FontWeight.w700)),
          ])),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
            decoration: BoxDecoration(color: kGreen.withOpacity(0.12), borderRadius: BorderRadius.circular(20)),
            child: Text(t('Activo', 'Active'),
              style: TextStyle(color: kGreen, fontSize: 10, fontWeight: FontWeight.w600))),
        ]),
        if (beneficio.isNotEmpty) ...[ 
          const SizedBox(height: 10),
          Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(color: kGreen.withOpacity(0.07), borderRadius: BorderRadius.circular(10)),
            child: Row(children: [
              const Text('🎁', style: TextStyle(fontSize: 14)),
              const SizedBox(width: 8),
              Expanded(child: Text(beneficio,
                style: const TextStyle(color: kText, fontSize: 12, fontWeight: FontWeight.w600, height: 1.3))),
            ])),
        ],
        if (direccion.isNotEmpty) ...[
          const SizedBox(height: 8),
          Row(children: [
            const Text('📍', style: TextStyle(fontSize: 12)),
            const SizedBox(width: 6),
            Expanded(child: Text(direccion,
              style: const TextStyle(color: kTextMuted, fontSize: 11))),
          ]),
        ],
        if (whatsapp.isNotEmpty) ...[
