              final beneficioMsg = beneficio.isNotEmpty ? beneficio : 'beneficio Rutero MDE';
              final codigo = codigoRuta?.isNotEmpty == true ? codigoRuta! : '—';
              final mensaje = Uri.encodeComponent(
                '¡Hola! Acabo de completar la $ruta en Rutero MDE. '
                'Soy uno de los exploradores que llegó hasta el final. '
                'Mi código es: $codigo — ¿cómo accedo al beneficio?');
