// ─── HOME — Avatar con nivel dinámico ──────────────────────────────────────────
class _HomeAvatarNivel extends StatelessWidget {
  const _HomeAvatarNivel();

  static const _niveles = [
    {'min': 0,    'emoji': '🌱'},
    {'min': 300,  'emoji': '🌿'},
    {'min': 700,  'emoji': '⛰️'},
    {'min': 1200, 'emoji': '🦅'},
    {'min': 2000, 'emoji': '🏆'},
  ];

  @override
  Widget build(BuildContext context) {
    if (AuthService.currentUser == null) {
      return Container(width: 48, height: 48,
        decoration: BoxDecoration(shape: BoxShape.circle,
          color: Colors.transparent,
          border: Border.all(color: kGold.withOpacity(0.4), width: 1.5)),
        child: const Center(child: Text('👤', style: TextStyle(fontSize: 22))));
    }
    return StreamBuilder<DocumentSnapshot>(
      stream: FirebaseFirestore.instance
        .collection('usuarios').doc(AuthService.currentUser!.uid).snapshots(),
      builder: (ctx, snap) {
        final data = snap.data?.data() as Map<String, dynamic>? ?? {};
        final int puntos = (data['puntosTotal'] ?? 0) as int;
        final nivel = _niveles.lastWhere(
          (n) => puntos >= (n['min'] as int), orElse: () => _niveles.first);
        final int nivelIdx = _niveles.indexOf(nivel) + 1;
        return Column(mainAxisSize: MainAxisSize.min, children: [
          Container(width: 48, height: 48,
            decoration: BoxDecoration(shape: BoxShape.circle,
              color: Colors.transparent,
              border: Border.all(color: kGold.withOpacity(0.5), width: 1.5),
              boxShadow: [BoxShadow(color: kGold.withOpacity(0.15), blurRadius: 8)]),
            child: ClipOval(child: AuthService.currentUser?.photoURL != null
              ? Image.network(AuthService.currentUser!.photoURL!,
                  fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => Center(
                    child: Text(nivel['emoji'] as String,
                      style: const TextStyle(fontSize: 24))))
              : Center(child: Text(nivel['emoji'] as String,
                  style: const TextStyle(fontSize: 24))))),
          const SizedBox(height: 4),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
            decoration: BoxDecoration(
              color: kGold.withOpacity(0.15),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: kGold.withOpacity(0.4))),
            child: Text('Nv. $nivelIdx',
              style: const TextStyle(
                fontFamily: 'SpaceGrotesk',
                fontSize: 9, color: kGold, fontWeight: FontWeight.w700))),
        ]);
      });
  }
}

