// ─────────────────────────────────────────────────────────────────────────
//  🌹 FERIA DE LAS FLORES — Countdown Widget
//  Muestra contador regresivo hasta el 31 de julio de 2026
//  + botón para ver los sitios que se van a visitar (abrebocas)
// ─────────────────────────────────────────────────────────────────────────
class _FeriaCountdownWidget extends StatefulWidget {
  const _FeriaCountdownWidget();
  @override
  State<_FeriaCountdownWidget> createState() => _FeriaCountdownWidgetState();
}

class _FeriaCountdownWidgetState extends State<_FeriaCountdownWidget> {
  late Timer _timer;
  Duration _restante = Duration.zero;
  bool _mostrarSitios = false;

  // Fecha de inicio Feria de las Flores 2026
  static final DateTime _fechaFeria = DateTime(2026, 7, 31, 8, 0, 0);

  static const List<String> _sitiosFeria = [
    '🎤 Parque de los Deseos — Trova y música',
    '🌸 Orquideorama — Exposición de flores',
    '🌾 Finca Silletera — Santa Elena',
    '🎪 Plaza Mayor — Exhibición de silletas',
    '🌺 Placita de Flórez — Plaza de Flores',
    '🎭 Avenida Guayabal — Desfile Silleteros',
    '🎵 Parques del Río — Tablado musical',
    '🏟️ Atanasio Girardot — Autos Clásicos',
  ];

  @override
  void initState() {
    super.initState();
    _actualizar();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) => _actualizar());
  }

  void _actualizar() {
    final ahora = DateTime.now();
    final diff = _fechaFeria.difference(ahora);
    if (mounted) setState(() => _restante = diff.isNegative ? Duration.zero : diff);
  }

  @override
  void dispose() {
    _timer.cancel();
    super.dispose();
  }

  String _pad(int n) => n.toString().padLeft(2, '0');

  @override
  Widget build(BuildContext context) {
    final dias   = _restante.inDays;
    final horas  = _restante.inHours % 24;
    final mins   = _restante.inMinutes % 60;
    final segs   = _restante.inSeconds % 60;
    final yaEsFeria = _restante == Duration.zero;

    return Container(
      margin: const EdgeInsets.only(bottom: 16),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          colors: [Color(0xFF1A0A10), Color(0xFF2A1020)],
          begin: Alignment.topLeft, end: Alignment.bottomRight),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: const Color(0xFFE85D26).withOpacity(0.4))),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // Header
        Row(children: [
          const Text('🌹', style: TextStyle(fontSize: 22)),
          const SizedBox(width: 8),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(t('FERIA DE LAS FLORES 2026', 'FERIA DE LAS FLORES 2026'),
              style: const TextStyle(color: kText, fontSize: 13, fontWeight: FontWeight.w900, letterSpacing: 0.5)),
            Text(t('Edición 69 · 31 jul – 9 ago · GRATIS', '69th Edition · Jul 31 – Aug 9 · FREE'),
              style: const TextStyle(color: kTextMuted, fontSize: 10)),
          ])),
        ]),
        const SizedBox(height: 8),
        // Lema oficial 2026
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
          decoration: BoxDecoration(
            color: kFeriaDorado.withOpacity(0.1),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(color: kFeriaDorado.withOpacity(0.3))),
          child: Text(t('"Medellín te quiere" 🌺', '"Medellín te quiere" 🌺'),
            style: const TextStyle(
              fontFamily: 'Inter',
              color: kFeriaDorado, fontSize: 11,
              fontStyle: FontStyle.italic,
              fontWeight: FontWeight.w600))),
        const SizedBox(height: 14),

        // Contador
        if (!yaEsFeria) ...[
          Text(t('FALTAN', 'STARTS IN'),
            style: const TextStyle(color: kTextMuted, fontSize: 9, letterSpacing: 2, fontWeight: FontWeight.w600)),
          const SizedBox(height: 8),
          Row(mainAxisAlignment: MainAxisAlignment.center, children: [
            _CountBox(valor: dias.toString(), label: t('DÍAS','DAYS')),
            _Sep(),
            _CountBox(valor: _pad(horas), label: t('HORAS','HRS')),
            _Sep(),
            _CountBox(valor: _pad(mins), label: t('MIN','MIN')),
            _Sep(),
            _CountBox(valor: _pad(segs), label: t('SEG','SEC')),
          ]),
        ] else ...[
          Center(child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            decoration: BoxDecoration(
              color: const Color(0xFFE85D26).withOpacity(0.15),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: const Color(0xFFE85D26).withOpacity(0.5))),
            child: Text(t('🌹 ¡LA FERIA HA COMENZADO!', '🌹 THE FESTIVAL HAS STARTED!'),
              style: const TextStyle(color: Color(0xFFE85D26), fontSize: 13, fontWeight: FontWeight.w900)))),
        ],

        const SizedBox(height: 14),

        // Botón abrebocas — ver sitios
        GestureDetector(
          onTap: () => setState(() => _mostrarSitios = !_mostrarSitios),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
            decoration: BoxDecoration(
              color: const Color(0xFFE85D26).withOpacity(0.1),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: const Color(0xFFE85D26).withOpacity(0.35))),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Text(_mostrarSitios ? '👆 ' : '👇 ', style: const TextStyle(fontSize: 13)),
              Text(
                _mostrarSitios
                  ? t('Ocultar sitios', 'Hide locations')
                  : t('Ver dónde vamos a ir 🌸', 'See where we will go 🌸'),
                style: const TextStyle(color: Color(0xFFE85D26), fontSize: 11, fontWeight: FontWeight.w700)),
            ]))),

        // Lista de sitios (abrebocas)
        if (_mostrarSitios) ...[
          const SizedBox(height: 10),
          ..._sitiosFeria.map((s) => Padding(
            padding: const EdgeInsets.only(bottom: 6),
            child: Row(children: [
              const SizedBox(width: 4),
              Expanded(child: Text(s,
                style: const TextStyle(color: kTextMuted, fontSize: 11, height: 1.4))),
            ]))),
        ],
      ]),
    );
  }
}

