// ─────────────────────────────────────────
class _ConsejosCard extends StatefulWidget {
  final Map<String, dynamic> ruta;
  const _ConsejosCard({required this.ruta});
  @override
  State<_ConsejosCard> createState() => _ConsejosCardState();
}

class _ConsejosCardState extends State<_ConsejosCard> {
  bool _expandido = false; // Usuario despliega manualmente
  @override
  Widget build(BuildContext context) {
    final List<String> consejos = List<String>.from(
      (kLang == 'en' ? widget.ruta['consejosEN'] : widget.ruta['consejos']) ?? []);
    if (consejos.isEmpty) return const SizedBox.shrink();
    final Color acento = kRutaColor(widget.ruta['acento'], kGreen);
    final String momentoClave = (kLang == 'en'
      ? widget.ruta['momentoClaveEN']
      : widget.ruta['momentoClave']) ?? '';
    return Container(
      margin: const EdgeInsets.only(bottom: 16),
      decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(16),
        border: Border.all(color: kGold.withOpacity(0.25))),
      child: Column(children: [
        GestureDetector(
          onTap: () => setState(() => _expandido = !_expandido),
          child: Container(padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
            child: Row(children: [
              Container(width: 36, height: 36,
                decoration: BoxDecoration(color: kGold.withOpacity(0.12), shape: BoxShape.circle),
                child: const Center(child: Text('🛡️', style: TextStyle(fontSize: 18)))),
              const SizedBox(width: 12),
              Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(t('Consejos de seguridad & experiencia', 'Safety & experience tips'),
                  style: const TextStyle(color: kText, fontSize: 13, fontWeight: FontWeight.w700)),
                Text(t('${consejos.length} recomendaciones para tu ruta', '${consejos.length} recommendations for your route'),
                  style: const TextStyle(color: kTextMuted, fontSize: 11)),
              ])),
              Icon(_expandido ? Icons.keyboard_arrow_up : Icons.keyboard_arrow_down,
                color: kGold.withOpacity(0.7), size: 20),
            ]))),
        if (_expandido) ...[
          Container(height: 1, color: kGold.withOpacity(0.1)),
          Padding(padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              ...consejos.map((c) => Padding(padding: const EdgeInsets.only(bottom: 10),
                child: Text(c, style: const TextStyle(color: kText, fontSize: 12, height: 1.4)))),
              if (momentoClave.isNotEmpty) ...[
                const SizedBox(height: 4),
                Container(padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(color: acento.withOpacity(0.08),
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(color: acento.withOpacity(0.25))),
                  child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    const Text('⭐', style: TextStyle(fontSize: 16)),
