// ═══════════════════════════════════════════════════════════════════════════════
//  FERIA DE LAS FLORES — PANTALLA PRINCIPAL
// ═══════════════════════════════════════════════════════════════════════════════

class FeriaScreen extends StatefulWidget {
  const FeriaScreen({super.key});
  @override
  State<FeriaScreen> createState() => _FeriaScreenState();
}

class _FeriaScreenState extends State<FeriaScreen> with SingleTickerProviderStateMixin {
  late TabController _tabCtrl;
  int _diaSeleccionado = -1; // -1 = hoy

  @override
  void initState() {
    super.initState();
    _tabCtrl = TabController(length: 4, vsync: this);
    // Notificaciones de la feria
    _programarNotificaciones();
  }

  @override
  void dispose() { _tabCtrl.dispose(); super.dispose(); }

  Future<void> _programarNotificaciones() async {
    // Solo programar si la feria no ha pasado
    if (diasParaFeria > -10) {
      await NotificationManager().programarFeria();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kDark2,
      body: NestedScrollView(
        headerSliverBuilder: (context, _) => [
          SliverToBoxAdapter(
            child: ValueListenableBuilder<String>(
              valueListenable: langNotifier,
              builder: (_, __, ___) => _FeriaHeader(diasParaFeria: diasParaFeria))),
          SliverPersistentHeader(
            pinned: true,
            delegate: _FeriaTabDelegate(tabController: _tabCtrl),
          ),
        ],
        body: TabBarView(
          controller: _tabCtrl,
          children: [
            _FeriaAgendaTab(),
            _FeriaRutasTab(),
            _FeriaTableadosTab(),
            _FeriaGuiaTab(),
          ],
        ),
      ),
    );
  }
}

// ─── HEADER ────────────────────────────────────────────────────────────────────
class _FeriaHeader extends StatelessWidget {
  final int diasParaFeria;
  const _FeriaHeader({required this.diasParaFeria});

  @override
  Widget build(BuildContext context) {
    final activa = diasParaFeria <= 0 && diasParaFeria >= -10;
    final terminada = diasParaFeria < -10;
    // Contenido primero — imagen se adapta al alto del contenido
    return LayoutBuilder(builder: (context, constraints) {
      return Stack(children: [
        // Fondo hero: ocupa todo el alto que defina el contenido
        Positioned.fill(
          child: Image.asset('assets/images/feria_hero.jpg', fit: BoxFit.cover,
            errorBuilder: (_, __, ___) => Container(
              decoration: const BoxDecoration(gradient: LinearGradient(
                begin: Alignment.topLeft, end: Alignment.bottomRight,
                colors: [Color(0xFF1A0A10), Color(0xFF2A1020), Color(0xFF0D1209)])))),
        ),
        // Gradiente oscuro encima de la imagen
        Positioned.fill(
          child: Container(decoration: const BoxDecoration(gradient: LinearGradient(
            begin: Alignment.topCenter, end: Alignment.bottomCenter,
            stops: [0.0, 0.4, 0.75, 1.0],
            colors: [Color(0x88000000), Color(0x44000000), Color(0xBB000000), Color(0xFF0D1209)]))),
        ),
        // Contenido — define el alto real del Stack
        SafeArea(
          bottom: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 16, 20, 24),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              // Badge edición
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                decoration: BoxDecoration(
                  color: kFeriaRojo.withOpacity(0.25),
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: kFeriaRojo.withOpacity(0.5))),
                child: Text(
                  t('🌹 69ª Edición · Medellín', '🌹 69th Edition · Medellín'),
                  style: const TextStyle(fontSize: 10, color: kFeriaRojo,
                    fontWeight: FontWeight.w700, letterSpacing: 0.5))),
              const SizedBox(height: 12),

              // Título display grande
              Text(t('FERIA DE\nLAS FLORES', 'FLOWER\nFESTIVAL'),
                style: const TextStyle(
                  fontFamily: 'PlayfairDisplay',
                  fontSize: 44, fontWeight: FontWeight.w900,
                  color: kText, letterSpacing: -1, height: 0.95)),
              Text('2026',
                style: const TextStyle(
                  fontFamily: 'PlayfairDisplay',
                  fontSize: 44, fontWeight: FontWeight.w900,
                  color: kFeriaDorado, letterSpacing: -1, height: 1.05)),
              const SizedBox(height: 4),
              Text(t('"Medellín te quiere" 🌺', '"Medellín te quiere" 🌺'),
                style: TextStyle(fontSize: 12, color: kText.withOpacity(0.75),
                  fontStyle: FontStyle.italic)),
              const SizedBox(height: 14),

              // Countdown / estado
              if (activa)
                _FeriaCountdownHoy()
              else if (terminada)
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(10)),
                  child: Text(
                    t('La Feria 2026 ha concluido · Hasta el año que viene 🌹',
                      'Festival 2026 has concluded · See you next year 🌹'),
                    style: TextStyle(fontSize: 12, color: kTextMuted)))
              else
                _FeriaCountdownDias(dias: diasParaFeria),

              const SizedBox(height: 12),

              // Stats chips
              Row(children: [
                _FeriaStatChip('21', t('tablados','stages'), kGreen),
                const SizedBox(width: 6),
                _FeriaStatChip('3', t('rutas','routes'), kFeriaDorado),
                const SizedBox(width: 6),
                _FeriaStatChip('🎵', t('eventos','events'), kFeriaRojo),
              ]),
              const SizedBox(height: 12),

              // Widget gamificación
              _FeriaGameStats(),
            ]))),
      ]);
    });
  }
}

// ─── GAMIFICACIÓN EN FERIA ──────────────────────────────────────────────────────
class _FeriaGameStats extends StatelessWidget {
  const _FeriaGameStats();

  static const _niveles = [
    {'min': 0,    'emoji': '🌱', 'nombre': 'Novato Rutero',       'nombreEN': 'Rutero Novice'},
    {'min': 300,  'emoji': '🌿', 'nombre': 'Explorador Urbano',   'nombreEN': 'Urban Explorer'},
    {'min': 700,  'emoji': '⛰️', 'nombre': 'Rutero Paisa',        'nombreEN': 'Paisa Rutero'},
    {'min': 1200, 'emoji': '🦅', 'nombre': 'Aventurero MDE',      'nombreEN': 'MDE Adventurer'},
    {'min': 2000, 'emoji': '🏆', 'nombre': 'Leyenda de Medellín', 'nombreEN': 'Medellín Legend'},
  ];

  @override
  Widget build(BuildContext context) {
    if (AuthService.currentUser == null) return const SizedBox.shrink();
    return StreamBuilder<DocumentSnapshot>(
      stream: FirebaseFirestore.instance
        .collection('usuarios')
        .doc(AuthService.currentUser!.uid)
        .snapshots(),
      builder: (ctx, snap) {
        final data = snap.data?.data() as Map<String, dynamic>? ?? {};
        final int puntos = (data['puntosTotal'] ?? 0) as int;
        final int sitios = (data['sitiosVisitados'] ?? 0) as int;
        final nivel = _niveles.lastWhere(
          (n) => puntos >= (n['min'] as int), orElse: () => _niveles.first);
        final int nivelIndex = _niveles.indexOf(nivel) + 1;

        return Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: Colors.black.withOpacity(0.55),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: kFeriaDorado.withOpacity(0.25))),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(t('Tu aventura en Medellín', 'Your Medellín adventure'),
              style: const TextStyle(fontSize: 11, color: kFeriaDorado,
                fontWeight: FontWeight.w700, letterSpacing: 0.5)),
            const SizedBox(height: 10),
            Row(children: [
              _GameStatCell(
                emoji: nivel['emoji'] as String,
                valor: 'Nivel $nivelIndex',
                label: t(nivel['nombre'] as String, nivel['nombreEN'] as String),
                color: kGreen),
              const SizedBox(width: 8),
              _GameStatCell(
                emoji: '🌸',
                valor: '$sitios',
                label: t('flores', 'flowers'),
                color: kFeriaRojo),
              const SizedBox(width: 8),
              _GameStatCell(
                emoji: '⭐',
                valor: '$puntos',
                label: t('puntos', 'points'),
                color: kFeriaDorado),
            ]),
          ]));
      });
  }
}

