class _FeriaTableadosTabState extends State<_FeriaTableadosTab> {
  int _zonaSeleccionada = -1;

  @override
  Widget build(BuildContext context) {
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        // Intro
        Container(
          margin: const EdgeInsets.only(bottom: 16),
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: kCard, borderRadius: BorderRadius.circular(12),
            border: Border.all(color: kGreen.withOpacity(0.2))),
          child: Text(
            t('21 tablados musicales · GRATIS · Toda la feria. Esponsorados por Aguardiente Antioqueño y Pilsen · Una validación por zona',
              '21 free music stages · Throughout the festival. Sponsored by Aguardiente Antioqueño & Pilsen · One validation per zone'),
            style: TextStyle(fontSize: 12, color: kTextMuted, height: 1.5))),
        // Zonas
        ...kFeriaZonasTablero.asMap().entries.map((entry) {
          final i = entry.key;
          final zona = entry.value;
          final sel = i == _zonaSeleccionada;
          return GestureDetector(
            onTap: () => setState(() => _zonaSeleccionada = sel ? -1 : i),
            child: Container(
              margin: const EdgeInsets.only(bottom: 8),
              decoration: BoxDecoration(
                color: sel ? (zona['color'] as Color) : kCard,
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                  color: sel ? kGreen.withOpacity(0.5) : kTextMuted.withOpacity(0.1))),
              child: Column(children: [
                Padding(
                  padding: const EdgeInsets.all(14),
                  child: Row(children: [
                    Text(zona['emoji'] as String, style: const TextStyle(fontSize: 24)),
                    const SizedBox(width: 12),
                    Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text(zona['zona'] as String,
                        style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: kText)),
                      Text('${(zona['tablados'] as List).length}' + t(' tablados · Validar uno',' stages · Validate one'),
                        style: const TextStyle(fontSize: 11, color: kTextMuted)),
                    ])),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(
                        color: kGreen.withOpacity(0.15),
                        borderRadius: BorderRadius.circular(6)),
                      child: const Text('GPS', style: TextStyle(fontSize: 10, color: kGreen, fontWeight: FontWeight.w700))),
                    const SizedBox(width: 8),
                    Text(sel ? '▲' : '▼', style: const TextStyle(color: kTextMuted, fontSize: 12)),
                  ])),
                if (sel) ...[
                  const Divider(height: 1, color: Colors.white10),
                  Padding(
                    padding: const EdgeInsets.all(14),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        ...(zona['tablados'] as List).map<Widget>((t) =>
                          Padding(
                            padding: const EdgeInsets.symmetric(vertical: 4),
                            child: Row(children: [
                              const Text('🎶', style: TextStyle(fontSize: 14)),
                              const SizedBox(width: 8),
                              Text(t.toString(),
                                style: const TextStyle(fontSize: 13, color: kText)),
                            ]))).toList(),
                        const SizedBox(height: 10),
                        if (zona['transporte'] != null)
                          Text(zona['transporte'] as String,
                            style: const TextStyle(fontSize: 11, color: kTextMuted)),
                        const SizedBox(height: 8),
                        GestureDetector(
                          onTap: () {
                            final lat = zona['lat'] as double;
                            final lng = zona['lng'] as double;
                            final url = 'https://www.google.com/maps/dir/?api=1&destination=\$lat,\$lng&travelmode=transit';
                            launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
                          },
                          child: Container(
                            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                            decoration: BoxDecoration(
                              color: kGreen.withOpacity(0.12),
                              borderRadius: BorderRadius.circular(8),
                              border: Border.all(color: kGreen.withOpacity(0.3))),
                            child: Row(mainAxisSize: MainAxisSize.min, children: [
                              const Text('🗺️', style: TextStyle(fontSize: 14)),
                              const SizedBox(width: 6),
                              Text(t('Cómo llegar a esta zona','Get directions to this zone'),
                                style: TextStyle(fontSize: 12, color: kGreen, fontWeight: FontWeight.w600)),
                            ]))),
                      ])),
                ],
              ])));
        }),
      ]);
  }
}

