//  PANTALLA DETALLE DE RUTA FERIA
// ═══════════════════════════════════════════════════════════════════════════════

class FeriaRutaDetailScreen extends StatelessWidget {
  final Map<String, dynamic> rutaFeria;
  const FeriaRutaDetailScreen({super.key, required this.rutaFeria});

  // Mapeo de id de ruta Feria → nombre en kRutasData
  static const Map<String, String> _idToNombre = {
    'feria_clasica':    'FERIA CLÁSICA',
    'feria_tablados':   'TABLADOS Y RUMBA',
    'feria_silletera':  'RUTA SILLETERA',
  };

  @override
  Widget build(BuildContext context) {
    // Buscar la ruta correcta en kRutasData según el id
    final nombreBuscado = _idToNombre[rutaFeria['id'] as String] ?? rutaFeria['nombre'] as String;
    final rutaCompleta = RutasService().rutas.firstWhere(
      (r) => r['nombre'] == nombreBuscado,
      orElse: () => rutaFeria);

    return Scaffold(
      backgroundColor: kDark2,
      body: CustomScrollView(slivers: [
        SliverAppBar(
          expandedHeight: 200,
          backgroundColor: rutaFeria['color1'] as Color,
          leading: GestureDetector(
            onTap: () => Navigator.pop(context),
            child: Container(
              margin: const EdgeInsets.all(8),
              decoration: BoxDecoration(color: Colors.black38, shape: BoxShape.circle),
              child: const Icon(Icons.arrow_back, color: Colors.white))),
          flexibleSpace: FlexibleSpaceBar(
            background: Container(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topLeft, end: Alignment.bottomRight,
                  colors: [rutaFeria['color1'] as Color, rutaFeria['color2'] as Color])),
              child: Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                const SizedBox(height: 40),
                Text(rutaFeria['emoji'] as String, style: const TextStyle(fontSize: 48)),
                const SizedBox(height: 8),
                Text(t(rutaFeria['nombre'] as String, rutaFeria['nombreEN'] as String),
                  style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w900,
                    color: kText, letterSpacing: 2)),
              ])))),
        ),
        SliverList(delegate: SliverChildListDelegate([
          Padding(
            padding: const EdgeInsets.all(20),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              // Descripción
              Text(t(rutaFeria['desc'] as String, rutaFeria['descEN'] as String),
                style: const TextStyle(fontSize: 14, color: kTextMuted, height: 1.6)),
              const SizedBox(height: 20),
              // Validación por fecha
              _FechaValidacionInfo(rutaId: rutaFeria['id'] as String),
              const SizedBox(height: 20),
              // Botón iniciar
              GestureDetector(
                onTap: () {
                  // Navegar a RouteDetailScreen con la ruta completa
                  if (rutaCompleta.containsKey('sitiosList')) {
                    RuteroNav.push(context, RouteDetailScreen(ruta: rutaCompleta));
                  }
                },
                child: Container(
                  width: double.infinity,
                  padding: const EdgeInsets.symmetric(vertical: 16),
                  decoration: BoxDecoration(
                    color: kRutaColor(rutaFeria['acento'], kGold).withOpacity(0.15),
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(color: kRutaColor(rutaFeria['acento'], kGold).withOpacity(0.5))),
                  child: Center(child: Text(
                    t('Iniciar ruta · ${rutaFeria['sitios']} sitios', 'Start route · ${rutaFeria['sitios']} sites'),
                    style: TextStyle(fontSize: 15, fontWeight: FontWeight.w800,
                      color: rutaFeria['acento'] as Color, letterSpacing: 1))))),
            ])),
        ])),
      ]));
  }
}

class _FechaValidacionInfo extends StatelessWidget {
  final String rutaId;
  const _FechaValidacionInfo({required this.rutaId});

  @override
  Widget build(BuildContext context) {
    final List<Map<String, dynamic>> eventos;
    switch (rutaId) {
      case 'feria_clasica':
        eventos = [
          {'emoji': '🌹', 'titulo': 'Desfile de Silleteros', 'fecha': '9 ago · 2 pm', 'fechaData': kFeriaDesfile},
          {'emoji': '🎸', 'titulo': 'Super Concierto', 'fecha': '8 ago · 7 pm', 'fechaData': kFeriaConcierto},
          {'emoji': '🎤', 'titulo': 'Final de la Trova', 'fecha': '7 ago · 6 pm', 'fechaData': kFeriaTrova},
          {'emoji': '🚗', 'titulo': 'Autos Clásicos', 'fecha': '6 ago · 10 am', 'fechaData': kFeriaAutos},
        ];
      case 'feria_silletera':
        eventos = [
          {'emoji': '🌿', 'titulo': 'Fincas silleteras', 'fecha': '19 jul – 9 ago', 'fechaData': null},
          {'emoji': '🏔️', 'titulo': 'Parque Arví', 'fecha': 'Toda la feria', 'fechaData': null},
        ];
      default:
        return const SizedBox.shrink();
    }

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: kCard,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: kFeriaDorado.withOpacity(0.2))),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(t('📅 VALIDACIÓN POR FECHA','📅 DATE VALIDATION'),
            style: TextStyle(fontSize: 10, color: kFeriaDorado,
              fontWeight: FontWeight.w700, letterSpacing: 1)),
          const SizedBox(height: 10),
          for (final e in eventos) ...[
            Builder(builder: (_) {
              final fechaData = e['fechaData'] as List<int>?;
              final esHoy2 = fechaData != null ? esDiaEvento(fechaData) : false;
              final diasFaltan = fechaData != null ? diasParaEvento(fechaData) : 0;
              return Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: Row(children: [
                  Text(e['emoji'] as String, style: const TextStyle(fontSize: 16)),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(e['titulo'] as String,
                          style: const TextStyle(fontSize: 12,
                            fontWeight: FontWeight.w600, color: kText)),
                        Text(e['fecha'] as String,
                          style: const TextStyle(fontSize: 10, color: kTextMuted)),
                      ])),
                  if (esHoy2)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                      decoration: BoxDecoration(
                        color: kGreen.withOpacity(0.2),
                        borderRadius: BorderRadius.circular(6)),
                      child: Text(t('¡HOY!','TODAY!'),
                        style: TextStyle(fontSize: 9, color: kGreen,
                          fontWeight: FontWeight.w800)))
                  else if (fechaData != null && diasFaltan > 0)
                    Text('en $diasFaltan días',
                      style: const TextStyle(fontSize: 10, color: kTextMuted)),
                ]));
            }),
          ],
          const Divider(color: Colors.white10, height: 16),
          Text(
            t('Los sitios de evento único solo se pueden validar en su día específico',
              'Single-event spots can only be validated on their specific day'),
            style: TextStyle(fontSize: 10, color: kTextMuted, height: 1.4)),
        ]));
  }
}

// ─── PAINTER FERIA ─────────────────────────────────────────────────────────────
class _FeriaPatternPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = kFeriaRojo.withOpacity(0.04)..style = PaintingStyle.fill;
    // Pétalos decorativos
    for (double x = 0; x < size.width; x += 50) {
      for (double y = 0; y < size.height; y += 50) {
        canvas.drawCircle(Offset(x, y), 2, paint);
      }
    }
  }
  @override
  bool shouldRepaint(_) => false;
}

// ─────────────────────────────────────────
//  PAINTERS
// ─────────────────────────────────────────

// Patrón de hojas estilizadas — identidad paisa
class _LeafPatternPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = kGreen.withOpacity(0.04)
      ..strokeWidth = 1
      ..style = PaintingStyle.stroke;

    // Líneas diagonales suaves
    const spacing = 32.0;
    for (double i = -size.height; i < size.width + size.height; i += spacing) {
      canvas.drawLine(Offset(i, 0), Offset(i + size.height, size.height), paint);
    }

    // Puntos decorativos tipo flor
    final dotPaint = Paint()
      ..color = kGold.withOpacity(0.06)
      ..style = PaintingStyle.fill;

    for (double x = 0; x < size.width; x += 60) {
      for (double y = 0; y < size.height; y += 60) {
        canvas.drawCircle(Offset(x + 30, y + 30), 1.5, dotPaint);
      }
    }
  }
  @override
  bool shouldRepaint(_) => false;
}